function cryptoId(){return 'id'+Math.random().toString(36).slice(2)+Date.now().toString(36)}
let state=load();let modalType='income';
function normalizeState(s){s=s||{};s.rates=s.rates||{USD:3.65,USDT:3.65};s.accounts=s.accounts||[];s.courses=(s.courses||[]).map(c=>({...c,id:c.id||cryptoId(),status:c.status||'Publicado'}));s.receivables=(s.receivables||[]).map(r=>({...r,id:r.id||cryptoId()}));s.payables=(s.payables||[]).map(r=>({...r,id:r.id||cryptoId(),status:r.status||'Pendiente'}));s.budgets=(s.budgets||[]).map(b=>({...b,id:b.id||cryptoId(),match:b.match||b.name||''}));s.goals=(s.goals||[]).map(g=>normalizeGoal(g));s.projects=(s.projects||[]).map(p=>normalizeProject(p));s.commercialProfiles=(s.commercialProfiles||[]).map(p=>normalizeCommercialProfile(p));s.quickReplies=(s.quickReplies||[]).map(r=>({...r,id:r.id||cryptoId(),category:r.category||'General',title:r.title||'Respuesta rápida',text:r.text||'',updatedAt:r.updatedAt||''}));s.transactions=s.transactions||[];return s}
function normalizeGoal(g){let metric=g.metric||g.type||'income';return {...g,id:g.id||cryptoId(),kind:g.kind||'financial',metric,period:g.period||'monthly',status:g.status||'En progreso',priority:g.priority||'Media',category:g.category||'Finanzas',startDate:g.startDate||periodStart(g.period||'monthly'),endDate:g.endDate||periodEnd(g.period||'monthly'),subtasks:(g.subtasks||[]).map(t=>({...t,id:t.id||cryptoId(),done:!!t.done})),target:Number(g.target||0)}}
function normalizeProject(p){return {...p,id:p.id||cryptoId(),type:p.type||'Creación de curso',status:p.status||'Idea',priority:p.priority||'Media',startDate:p.startDate||todayISO(),targetDate:p.targetDate||'',futurePrice:Number(p.futurePrice||0),responsible:p.responsible||'Administrador',category:p.category||'Creación de cursos',description:p.description||'',notes:p.notes||'',stages:(p.stages||defaultStages()).map(x=>({...x,id:x.id||cryptoId(),status:x.status||'Pendiente'})),modules:(p.modules||[]).map(m=>({...m,id:m.id||cryptoId(),lessons:(m.lessons||[]).map(l=>({...l,id:l.id||cryptoId(),status:l.status||'Pendiente'}))})),costs:(p.costs||[]).map(c=>({...c,id:c.id||cryptoId(),amount:Number(c.amount||0)})),courseId:p.courseId||null,published:!!p.published}}
function normalizeCommercialProfile(p){return {...p,id:p.id||cryptoId(),courseId:p.courseId||null,productName:p.productName||'',status:p.status||'Activo',audience:p.audience||'',modality:p.modality||'',duration:p.duration||'',level:p.level||'',certificate:p.certificate||'',priceText:p.priceText||'',paymentMethods:p.paymentMethods||'',shortMessage:p.shortMessage||'',fullMessage:p.fullMessage||'',syllabus:p.syllabus||'',benefits:p.benefits||'',requirements:p.requirements||'',faq:p.faq||'',closing:p.closing||'',link:p.link||'',notes:p.notes||'',updatedAt:p.updatedAt||''}}
function load(){try{let v=JSON.parse(localStorage.getItem('pasir_finanzas_v1'));if(v){v=normalizeState(v);localStorage.setItem('pasir_finanzas_v1',JSON.stringify(v));return v}}catch(e){}let s=normalizeState(JSON.parse(JSON.stringify(DEMO)));s.transactions=demoTx();localStorage.setItem('pasir_finanzas_v1',JSON.stringify(s));return s}
function persist(){localStorage.setItem('pasir_finanzas_v1',JSON.stringify(state));renderAll()}
function fmt(v,c='PEN'){let n=Number(v||0);if(c==='PEN')return 'S/ '+n.toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});return n.toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+c}
function toPen(amount,c){return Number(amount)*(c==='PEN'?1:(state.rates[c]||1))}
function monthTx(){let n=new Date();return state.transactions.filter(t=>{let x=new Date(t.date+'T12:00:00');return x.getMonth()===n.getMonth()&&x.getFullYear()===n.getFullYear()})}
function totals(){let tx=monthTx();let income=0,expense=0,personal=0,withdraw=0;tx.forEach(t=>{let v=toPen(t.amount,t.currency);if(t.type==='income')income+=v;if(t.type==='expense')expense+=v;if(t.type==='personal')personal+=v;if(t.type==='owner_withdrawal')withdraw+=v});let balance=state.accounts.reduce((s,a)=>s+toPen(a.balance,a.currency),0);return{income,expense,personal,withdraw,profit:income-expense,balance}}
function renderNav(){let last='';document.getElementById('nav').innerHTML=NAV.map((n,i)=>{let head=n[3]!==last?`<div class="nav-group">${n[3]}</div>`:'';last=n[3];return head+`<button class="${i===0?'active':''}" data-screen="${n[0]}" onclick="showScreen('${n[0]}')"><span>${n[1]}</span>${n[2]}</button>`}).join('')}
function showScreen(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));let el=document.getElementById('screen-'+id);if(!el)return;el.classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.screen===id));document.getElementById('pageTitle').textContent=NAV.find(x=>x[0]===id)?.[2]||(id==='project-detail'?'Proyecto':id==='goal-detail'?'Meta':'PASIR Gestión');document.getElementById('sidebar').classList.remove('open');updateTopActions(id);renderAll()}
function renderStats(){let t=totals();let data=[['Saldo total',fmt(t.balance),'Todas tus cuentas'],['Ingresos del mes',fmt(t.income),'+ ventas registradas'],['Gastos del negocio',fmt(t.expense),'Operativos'],['Utilidad del mes',fmt(t.profit),'Ingresos − gastos'],['Gastos personales',fmt(t.personal+t.withdraw),'Separados del negocio']];document.getElementById('stats').innerHTML=data.map((x,i)=>`<div class="card stat"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="trend ${i===3&&t.profit>=0?'ok':''}">${x[2]}</div></div>`).join('')}
function renderAccounts(){let dash=state.accounts.map(a=>`<div class="card account"><h3>${a.name}</h3><div class="balance">${fmt(a.balance,a.currency)}</div><div class="meta"><span>${a.type}</span><span>≈ ${fmt(toPen(a.balance,a.currency))}</span></div></div>`).join('');let all=state.accounts.map(a=>`<div class="card account"><h3>${a.name}</h3><div class="balance">${fmt(a.balance,a.currency)}</div><div class="meta"><span>${a.type}</span><span>≈ ${fmt(toPen(a.balance,a.currency))}</span></div><div class="card-actions"><button class="btn sm" onclick="editAccount('${a.id}')">Editar</button><button class="btn sm" onclick="deleteAccount('${a.id}')">Eliminar</button></div></div>`).join('');document.getElementById('accountCards').innerHTML=dash||'<div class="empty">No hay cuentas.</div>';document.getElementById('allAccounts').innerHTML=all||'<div class="empty">No hay cuentas. Usa “Nueva cuenta” para crear la primera.</div>'}
function txLabel(t){return ({income:'Ingreso',expense:'Gasto negocio',personal:'Gasto personal',transfer:'Transferencia',owner_withdrawal:'Retiro propietario',capital:'Aporte capital'})[t.type]||t.type}
function accountName(id){return state.accounts.find(a=>a.id===id)?.name||'—'}
function txRows(list){return `<div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Concepto</th><th>Cuenta</th><th>Categoría</th><th>Monto</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td>${t.date}</td><td><span class="badge ${t.type==='income'?'income':t.type==='expense'?'expense':t.type==='transfer'?'transfer':'personal'}">${txLabel(t)}</span></td><td>${esc(t.concept||'—')}</td><td>${t.type==='transfer'?esc(accountName(t.from))+' → '+esc(accountName(t.to)):esc(accountName(t.account))}</td><td>${esc(t.category||'—')}</td><td class="amount ${t.type==='income'||t.type==='capital'?'pos':t.type==='transfer'?'':'neg'}">${t.type==='income'||t.type==='capital'?'+':t.type==='transfer'?'':'−'}${fmt(t.amount,t.currency)}</td><td><button class="btn sm" onclick="deleteTx('${t.id}')">×</button></td></tr>`).join('')}</tbody></table></div>`}
function renderRecent(){let list=[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,7);document.getElementById('recentTable').innerHTML=txRows(list)}
function renderMovements(){let q=(document.getElementById('searchMove')?.value||'').toLowerCase(),ft=document.getElementById('filterType')?.value||'';let l=[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).filter(t=>(!ft||t.type===ft)&&(!q||[t.concept,t.category,accountName(t.account),accountName(t.from),accountName(t.to)].join(' ').toLowerCase().includes(q)));document.getElementById('movementTable').innerHTML=l.length?txRows(l):'<div class="empty">No hay movimientos que coincidan.</div>'}
function renderInsights(){let t=totals(),tx=monthTx(),hotmart=tx.filter(x=>accountName(x.account)==='Hotmart'&&x.type==='income').reduce((s,x)=>s+toPen(x.amount,x.currency),0);let marketing=tx.filter(x=>x.type==='expense'&&/marketing|ads|publicidad/i.test(x.category+' '+x.concept)).reduce((s,x)=>s+toPen(x.amount,x.currency),0);let margin=t.income?Math.round(t.profit/t.income*100):0;let arr=[`Tu margen neto del mes es <b>${margin}%</b>.`,`Marketing representa <b>${t.expense?Math.round(marketing/t.expense*100):0}%</b> de los gastos operativos.`,`Las transferencias internas registradas no modifican la utilidad.`,`Tienes <b>${fmt(t.balance)}</b> de saldo consolidado aproximado.`];document.getElementById('insights').innerHTML=arr.map(x=>`<div class="insight">${x}</div>`).join('')}
function renderChart(){let now=new Date(),months=[];for(let k=5;k>=0;k--){let d=new Date(now.getFullYear(),now.getMonth()-k,1);let m=d.getMonth(),y=d.getFullYear();let l=state.transactions.filter(t=>{let x=new Date(t.date+'T12:00:00');return x.getMonth()===m&&x.getFullYear()===y});let inc=l.filter(x=>x.type==='income').reduce((s,x)=>s+toPen(x.amount,x.currency),0),exp=l.filter(x=>x.type==='expense').reduce((s,x)=>s+toPen(x.amount,x.currency),0);months.push({name:d.toLocaleString('es',{month:'short'}),inc,exp})}let max=Math.max(1,...months.flatMap(x=>[x.inc,x.exp]));document.getElementById('chart').innerHTML=months.map(x=>`<div class="bar-group"><div class="bar in" style="height:${Math.max(3,x.inc/max*90)}%" title="Ingresos ${fmt(x.inc)}"></div><div class="bar out" style="height:${Math.max(3,x.exp/max*90)}%" title="Gastos ${fmt(x.exp)}"></div><span class="month">${x.name}</span></div>`).join('')}
function renderPetty(){let a=state.accounts.find(x=>x.name.toLowerCase().includes('caja chica'));let tx=state.transactions.filter(t=>t.account===a?.id||t.from===a?.id||t.to===a?.id);document.getElementById('pettyContent').innerHTML=`<div class="grid stats" style="grid-template-columns:repeat(3,1fr)"><div class="card stat"><div class="label">Saldo actual</div><div class="value">${a?fmt(a.balance,a.currency):'—'}</div></div><div class="card stat"><div class="label">Movimientos</div><div class="value">${tx.length}</div></div><div class="card stat"><div class="label">Estado</div><div class="value" style="font-size:20px">${a&&a.balance<200?'Saldo bajo':'Disponible'}</div></div></div><div class="section">${tx.length?txRows(tx):'<div class="empty">Sin movimientos de caja chica.</div>'}</div>`}
function renderCourses(){let rows=state.courses.map(c=>{let sales=courseSalesCount(c),rev=courseRevenue(c);return `<tr><td>${esc(c.name)}<div class="course-link">${c.status||'Publicado'}${c.platform?' · '+esc(c.platform):''}</div></td><td>${fmt(c.price)}</td><td>${sales}</td><td class="amount pos">${fmt(rev)}</td><td><div style="display:flex;gap:6px"><button class="btn sm" onclick="openCommercialForCourse('${c.id}')">Ficha comercial</button><button class="btn sm" onclick="editCourse('${c.id}')">Editar</button><button class="btn sm" onclick="deleteCourse('${c.id}')">Eliminar</button></div></td></tr>`}).join('');document.getElementById('coursesContent').innerHTML=rows?`<div class="table-wrap"><table class="table"><thead><tr><th>Curso</th><th>Precio</th><th>Ventas registradas</th><th>Ingresos generados</th><th>Acciones</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="card empty">No hay cursos publicados. Puedes agregarlos manualmente o finalizar un proyecto de curso.</div>'}
function renderReceivables(){let total=state.receivables.reduce((s,r)=>s+Math.max(0,r.total-r.paid),0);let rows=state.receivables.map(r=>`<tr><td>${r.client}</td><td>${r.course}</td><td>${fmt(r.total)}</td><td>${fmt(r.paid)}</td><td class="amount neg">${fmt(Math.max(0,r.total-r.paid))}</td><td>${r.due||'—'}</td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn sm" onclick="editReceivable('${r.id}')">Editar</button><button class="btn sm" onclick="deleteReceivable('${r.id}')">Eliminar</button></div></td></tr>`).join('');document.getElementById('receivablesContent').innerHTML=`<div class="card stat" style="margin-bottom:14px"><div class="label">Total por cobrar</div><div class="value">${fmt(total)}</div></div>${rows?`<div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Curso</th><th>Total</th><th>Pagado</th><th>Pendiente</th><th>Próximo pago</th><th>Acciones</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="card empty">No hay cuentas por cobrar.</div>'}`}
function budgetSpent(b){let key=(b.match||b.name||'').trim().toLowerCase();if(!key)return 0;return monthTx().filter(x=>x.type==='expense').filter(t=>((t.category||'')+' '+(t.concept||'')).toLowerCase().includes(key)).reduce((s,t)=>s+toPen(t.amount,t.currency),0)}
function budgetStatus(raw){if(raw>100)return ['Excedido','danger-text'];if(raw>=90)return ['Muy cerca del límite','danger-text'];if(raw>=80)return ['Atención',''];return ['En control','']}
function renderBudgets(){let html=state.budgets.map(b=>{let spent=budgetSpent(b),raw=b.limit?Math.round(spent/b.limit*100):0,p=Math.min(100,raw),st=budgetStatus(raw);return `<div class="card"><div class="section-head"><div><h2>${b.name}</h2><span class="status-chip ${st[1]}">${st[0]}</span></div><b>${raw}%</b></div><div style="display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:8px"><span>Gastado ${fmt(spent)}</span><span>Presupuesto ${fmt(b.limit)}</span></div><div class="progress"><i style="width:${p}%"></i></div><div style="margin-top:9px;font-size:12px">Disponible: <b>${fmt(Math.max(0,b.limit-spent))}</b></div><div style="margin-top:6px;font-size:11px;color:var(--muted)">Controla movimientos que contengan: <b>${b.match||b.name}</b></div><div class="card-actions"><button class="btn sm" onclick="editBudget('${b.id}')">Editar</button><button class="btn sm" onclick="deleteBudget('${b.id}')">Eliminar</button></div></div>`}).join('');document.getElementById('budgetsContent').innerHTML=html?'<div class="grid accounts">'+html+'</div>':'<div class="card empty">No hay presupuestos. Crea el primero con “Nuevo presupuesto”.</div>'}
function periodStart(period){let n=new Date(),d=new Date(n);if(period==='daily'){}else if(period==='weekly'){let day=(n.getDay()+6)%7;d.setDate(n.getDate()-day)}else if(period==='quarterly'){d=new Date(n.getFullYear(),Math.floor(n.getMonth()/3)*3,1)}else if(period==='annual'){d=new Date(n.getFullYear(),0,1)}else d=new Date(n.getFullYear(),n.getMonth(),1);return d.toISOString().slice(0,10)}
function periodEnd(period){let n=new Date(),d;if(period==='daily')d=n;else if(period==='weekly'){let day=(n.getDay()+6)%7;d=new Date(n);d.setDate(n.getDate()-day+6)}else if(period==='quarterly')d=new Date(n.getFullYear(),Math.floor(n.getMonth()/3)*3+3,0);else if(period==='annual')d=new Date(n.getFullYear(),11,31);else d=new Date(n.getFullYear(),n.getMonth()+1,0);return d.toISOString().slice(0,10)}
function goalRange(g){return [g.startDate||periodStart(g.period),g.endDate||periodEnd(g.period)]}
function txInRange(t,a,b){return (!a||t.date>=a)&&(!b||t.date<=b)}
function goalCurrent(g){if(g.kind!=='financial'){let total=(g.subtasks||[]).length;return total?(g.subtasks.filter(x=>x.done).length/total*100):0}let [a,b]=goalRange(g),tx=state.transactions.filter(t=>txInRange(t,a,b));if(g.metric==='profit'){let inc=tx.filter(x=>x.type==='income').reduce((s,x)=>s+toPen(x.amount,x.currency),0),exp=tx.filter(x=>x.type==='expense').reduce((s,x)=>s+toPen(x.amount,x.currency),0);return inc-exp}if(g.metric==='balance')return totals().balance;if(g.metric==='sales')return tx.filter(x=>x.type==='income').length;if(g.metric==='course_sales')return tx.filter(x=>x.type==='income'&&courseMatch(x,g.courseId)).length;if(g.metric==='course_revenue')return tx.filter(x=>x.type==='income'&&courseMatch(x,g.courseId)).reduce((s,x)=>s+toPen(x.amount,x.currency),0);return tx.filter(x=>x.type==='income').reduce((s,x)=>s+toPen(x.amount,x.currency),0)}
function courseMatch(t,courseId){let c=state.courses.find(x=>x.id===courseId);return !!c&&(t.courseId===courseId||t.course===c.name)}
function goalTypeLabel(type){return {income:'Ingresos',profit:'Utilidad',balance:'Saldo total',sales:'Número de ventas',course_sales:'Ventas por curso',course_revenue:'Facturación por curso'}[type]||'Ingresos'}
function goalPeriodLabel(p){return {daily:'Diaria',weekly:'Semanal',monthly:'Mensual',quarterly:'Trimestral',annual:'Anual',custom:'Personalizada'}[p]||'Mensual'}
function goalProjection(g,cur){if(g.kind!=='financial'||['balance'].includes(g.metric)||!g.startDate||!g.endDate)return'';let a=new Date(g.startDate+'T12:00:00'),b=new Date(g.endDate+'T12:00:00'),n=new Date();let total=Math.max(1,Math.round((b-a)/86400000)+1),elapsed=Math.min(total,Math.max(1,Math.round((n-a)/86400000)+1)),remaining=Math.max(0,total-elapsed);if(n<a)return`La meta inicia el ${g.startDate}.`;if(n>b)return cur>=g.target?'Meta alcanzada en el periodo.':'El periodo terminó por debajo del objetivo.';let projection=cur/elapsed*total,need=Math.max(0,g.target-cur),daily=remaining?need/remaining:need;if(g.metric.includes('sales'))return projection>=g.target?`Al ritmo actual proyectas ${Math.round(projection)} ventas y superarías la meta.`:`Necesitas aproximadamente ${Math.ceil(daily)} ventas por día durante ${remaining} días.`;return projection>=g.target?`Al ritmo actual proyectas ${fmt(projection)} y superarías la meta en aproximadamente ${fmt(projection-g.target)}.`:`Para alcanzar la meta necesitas generar aproximadamente ${fmt(daily)} diarios durante ${remaining} días.`}
function renderGoals(){let financial=state.goals.filter(g=>g.kind==='financial');let html=financial.map(g=>goalCard(g)).join('');document.getElementById('goalsContent').innerHTML=`<div class="split-actions" style="margin-bottom:12px"><div class="info-strip"><span class="pill">${financial.filter(g=>g.status==='En progreso').length} activas</span><span class="pill">${financial.filter(g=>g.status==='Completado').length} completadas</span></div><button class="btn primary" onclick="addAdvancedGoal(true)">＋ Nueva meta</button></div>${html?'<div class="project-grid">'+html+'</div>':'<div class="card empty"><div class="empty-icon">◎</div>No hay metas financieras. Crea la primera; el avance se calculará automáticamente con tus movimientos.</div>'}`}
function goalCard(g){let cur=goalCurrent(g),isPct=g.kind!=='financial',raw=isPct?Math.round(cur):g.target?Math.round(cur/g.target*100):0,p=Math.max(0,Math.min(100,raw)),value=isPct?`${Math.round(cur)}%`:g.metric.includes('sales')?`${Math.round(cur)} / ${g.target}`:`${fmt(cur)} / ${fmt(g.target)}`;return `<div class="card goal-card clickable-card ${g.status==='Pausado'?'paused':''} ${g.status==='Completado'?'completed':''}" onclick="openGoal('${g.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openGoal('${g.id}')}" aria-label="Abrir meta ${esc(g.name)}"><div class="section-head"><div><span class="pill priority-${g.priority}">${g.priority}</span><h2 style="margin-top:8px">${esc(g.name)}</h2></div><span class="status-chip">${g.status}</span></div><div class="info-strip"><span class="pill">${g.kind==='financial'?goalTypeLabel(g.metric):g.category}</span>${g.kind==='financial'?`<span class="pill">${goalPeriodLabel(g.period)}</span>`:''}</div>${g.description?`<div class="goal-desc">${esc(g.description)}</div>`:''}<div class="value" style="font-size:22px;font-weight:900;margin-top:12px">${value}</div><div class="progress" style="margin-top:10px"><i style="width:${p}%"></i></div>${g.kind==='financial'?`<div class="projection">${goalProjection(g,cur)}</div>`:''}${g.kind!=='financial'?renderGoalTasksMini(g):''}<div class="card-open-hint">Toca la tarjeta para ver la meta completa →</div><div class="card-actions" onclick="event.stopPropagation()"><button class="btn sm" onclick="editAdvancedGoal('${g.id}')">Editar</button><button class="btn sm" onclick="duplicateGoal('${g.id}')">Duplicar</button><button class="btn sm" onclick="toggleGoalPause('${g.id}')">${g.status==='Pausado'?'Reabrir':'Pausar'}</button><button class="btn sm good" onclick="completeGoal('${g.id}')">Completar</button><button class="btn sm" onclick="resetGoal('${g.id}')">Reiniciar</button><button class="btn sm" onclick="deleteGoal('${g.id}')">Eliminar</button></div></div>`}
function renderGoalTasksMini(g){let st=g.subtasks||[],done=st.filter(x=>x.done).length;return `<div style="font-size:11px;color:var(--muted);margin-top:10px">Subtareas: <b>${done}/${st.length}</b></div><div style="margin-top:7px">${st.slice(0,6).map(t=>`<div class="task-row" onclick="event.stopPropagation()"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" ${t.done?'checked':''} onchange="toggleGoalTask('${g.id}','${t.id}')"> <span style="${t.done?'text-decoration:line-through;opacity:.65':''}">${esc(t.name)}</span></label></div>`).join('')}${st.length>6?`<div class="muted" style="font-size:10px;margin-top:5px">+${st.length-6} subtareas más</div>`:''}</div><div class="card-actions" onclick="event.stopPropagation()"><button class="btn sm" onclick="addGoalSubtask('${g.id}')">＋ Subtarea</button></div>`}
function renderReports(){let t=totals(),sales=monthTx().filter(x=>x.type==='income').length;document.getElementById('reportsContent').innerHTML=`<div class="grid stats" style="grid-template-columns:repeat(4,1fr)"><div class="card stat"><div class="label">Ventas</div><div class="value">${sales}</div></div><div class="card stat"><div class="label">Ingresos netos</div><div class="value">${fmt(t.income)}</div></div><div class="card stat"><div class="label">Gastos operativos</div><div class="value">${fmt(t.expense)}</div></div><div class="card stat"><div class="label">Margen</div><div class="value">${t.income?Math.round(t.profit/t.income*100):0}%</div></div></div><div class="card section"><h2 style="margin-top:0">Reglas financieras aplicadas</h2><p>Utilidad = ingresos del negocio − gastos operativos. Transferencias internas, aportes de capital, gastos personales y retiros del propietario no alteran la utilidad operacional.</p></div>`}
function renderAll(){renderStats();renderAccounts();renderRecent();renderMovements();renderInsights();renderChart();renderPetty();renderCourses();renderReceivables();renderPayables();renderBudgets();renderGoals();renderReports();renderSummary();renderProjects();renderDevelopment();renderCalendar();renderCommercial();renderSales();renderProfitability();renderPasirAnalysis();renderProjectDetail();renderGoalDetail();let u=document.getElementById('usdRate'),q=document.getElementById('usdtRate');if(u)u.value=state.rates.USD;if(q)q.value=state.rates.USDT}

let entityModalSubmit=null;
function updateTopActions(screenId){let el=document.getElementById('financeTopActions');if(!el)return;el.classList.toggle('hidden',screenId!=='dashboard')}
function modalBackdropClose(e,which){if(e.target!==e.currentTarget)return;if(which==='movement')closeModal();else closeEntityModal()}
function openEntityModal(cfg){document.getElementById('entityEyebrow').textContent=cfg.eyebrow||'ESCUELA PASIR';document.getElementById('entityTitle').textContent=cfg.title||'Nuevo registro';document.getElementById('entitySubtitle').textContent=cfg.subtitle||'';document.getElementById('entityBody').innerHTML=cfg.body||'';document.getElementById('entityHint').textContent=cfg.hint||'Completa los datos principales.';let b=document.getElementById('entitySaveBtn');b.textContent=cfg.saveLabel||'Guardar';b.className='btn '+(cfg.saveClass||'primary');entityModalSubmit=cfg.onSave;document.getElementById('entityModal').classList.remove('hidden');document.body.style.overflow='hidden';const eb=document.getElementById('entityBody');if(eb)eb.scrollTop=0;setTimeout(()=>document.querySelector('#entityBody input:not([type=hidden]),#entityBody select,#entityBody textarea')?.focus(),60)}
function closeEntityModal(){document.getElementById('entityModal').classList.add('hidden');entityModalSubmit=null;if(document.getElementById('modal').classList.contains('hidden'))document.body.style.overflow=''}
function submitEntityModal(){if(typeof entityModalSubmit==='function')entityModalSubmit()}
function val(id){return(document.getElementById(id)?.value||'').trim()}
function num(id){return Number(document.getElementById(id)?.value||0)}
function formSection(icon,title,content){return`<div class="form-section"><div class="form-section-title"><span class="form-icon">${icon}</span>${title}</div>${content}</div>`}
function options(list,selected=''){return list.map(x=>{let v=Array.isArray(x)?x[0]:x,l=Array.isArray(x)?x[1]:x;return`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(l)}</option>`}).join('')}
function openModal(type='income',forcedAccountName){
  modalType=type||'income';
  let titles={income:'Nuevo ingreso / venta',expense:'Nuevo gasto del negocio',personal:'Nuevo gasto personal',transfer:'Transferencia entre cuentas',owner_withdrawal:'Retiro del propietario',capital:'Aporte de capital'};
  document.getElementById('modalTitle').textContent=titles[modalType]||'Nuevo movimiento';
  document.getElementById('modalSubtitle').textContent=modalType==='transfer'?'Mueve dinero entre tus propias cuentas sin alterar la utilidad.':'Elige si es ingreso o gasto y escribe el monto siempre en positivo.';
  let accOpts=state.accounts.map(a=>`<option value="${a.id}" ${forcedAccountName&&a.name===forcedAccountName?'selected':''}>${esc(a.name)} — ${a.currency} · ${fmt(a.balance,a.currency)}</option>`).join('');
  let types=[['income','＋','Ingreso','Venta, asesoría o ingreso'],['expense','−','Gasto negocio','Costo operativo PASIR'],['personal','⌂','Gasto personal','Separado del negocio'],['transfer','↔','Transferencia','Entre tus cuentas'],['owner_withdrawal','⇣','Retiro propietario','Uso personal del capital'],['capital','⇡','Aporte de capital','Dinero que incorporas']];
  let typePicker=`<div class="movement-type-grid">${types.map(t=>`<button type="button" class="movement-type ${t[0]} ${modalType===t[0]?'active':''}" onclick="switchMovementType('${t[0]}','${forcedAccountName||''}')"><b>${t[1]} ${t[2]}</b><span>${t[3]}</span></button>`).join('')}</div>`;
  let amountBlock=`<div class="form-grid three"><div class="field"><label class="required">Fecha</label><input id="mDate" type="date" value="${todayISO()}"></div><div class="field"><label>Hora</label><input id="mTime" type="time" value="${new Date().toTimeString().slice(0,5)}"></div><div class="field"><label class="required">Monto</label><input id="mAmount" type="number" min="0" step="0.01" placeholder="0.00"><div class="field-help">No uses signo negativo. El tipo de movimiento define si suma o resta.</div></div></div>`;
  let body=formSection('↕','Tipo de movimiento',typePicker)+formSection('S/','Importe y fecha',amountBlock);
  if(modalType==='transfer'){
    body+=formSection('⇄','Origen y destino',`<div class="form-grid"><div class="field"><label class="required">Cuenta de origen</label><select id="mFrom" class="select-rich">${accOpts}</select></div><div class="field"><label class="required">Cuenta de destino</label><select id="mTo" class="select-rich">${accOpts}</select></div><div class="field"><label>Moneda</label><select id="mCurrency"><option>PEN</option><option>USD</option><option>USDT</option></select></div><div class="field"><label>Concepto</label><input id="mConcept" value="Transferencia entre cuentas"></div><div class="field span-2"><label>Nota</label><textarea id="mNotes" placeholder="Motivo o referencia interna (opcional)"></textarea></div></div>`)+`<div class="movement-summary"><span>ⓘ</span><div><strong>No es ingreso ni gasto.</strong> Se descuenta de una cuenta y se suma a la otra sin modificar la utilidad de Escuela PASIR.</div></div>`;
  }else{
    let catMap={income:['Venta de curso','Curso individual','Membresía','Suscripción','Taller','Capacitación','Asesoría','Venta Hotmart','Venta Google Play','Venta Microsoft Store','Otros ingresos'],expense:['Marketing','Facebook Ads','TikTok Ads','Google Ads','Software','Hosting','Dominio','Servidor','Producción','Edición','Equipos','Internet','Contabilidad','Comisiones','Personal','Impuestos','Otros gastos'],personal:['Alimentación','Transporte','Vivienda','Servicios','Educación','Familia','Salud','Ropa','Entretenimiento','Viajes','Compras','Deudas','Otros'],owner_withdrawal:['Retiro del propietario'],capital:['Aporte de capital']};
    let cats=catMap[modalType]||['Otros'];
    body+=formSection('▣','Clasificación',`<div class="form-grid"><div class="field"><label class="required">Cuenta</label><select id="mAccount" class="select-rich">${accOpts}</select></div><div class="field"><label>Moneda</label><select id="mCurrency"><option>PEN</option><option>USD</option><option>USDT</option></select></div><div class="field"><label class="required">Categoría</label><select id="mCategory">${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Concepto</label><input id="mConcept" placeholder="Ej. Facebook Ads septiembre, venta PLC LOGO..."></div></div>`);
    if(modalType==='income')body+=formSection('↗','Datos de la venta',`<div class="form-grid"><div class="field"><label>Cliente / alumno</label><input id="mCustomer" placeholder="Nombre del cliente"></div><div class="field"><label>Producto / Curso</label><select id="mCourse"><option value="">Sin vincular</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Medio de pago</label><select id="mPayment"><option>Yape</option><option>Plin</option><option>Transferencia bancaria</option><option>Hotmart</option><option>PayPal</option><option>Binance / USDT</option><option>Efectivo</option><option>Otro</option></select></div><div class="field"><label>Número de operación</label><input id="mOperation" placeholder="Opcional"></div></div>`);
    body+=formSection('✎','Detalle adicional',`<div class="form-grid"><div class="field span-2"><label>Notas</label><textarea id="mNotes" placeholder="Información adicional, proveedor, comprobante u observaciones"></textarea></div></div>`);
    let note=modalType==='expense'?'Se restará de la cuenta y se incluirá en los gastos operativos de PASIR.':modalType==='income'?'Se sumará a la cuenta y contará como ingreso del negocio.':modalType==='personal'?'Se restará de la cuenta, pero NO reducirá la utilidad operacional de PASIR.':modalType==='owner_withdrawal'?'Se registrará como retiro del propietario, no como gasto operativo.':'Se sumará como aporte de capital, no como venta.';
    body+=`<div class="movement-summary"><span>ⓘ</span><div>${note}</div></div>`;
  }
  document.getElementById('modalBody').innerHTML=body;
  document.getElementById('movementSaveBtn').textContent=modalType==='income'?'Guardar ingreso':modalType==='expense'?'Guardar gasto':modalType==='personal'?'Guardar gasto personal':modalType==='transfer'?'Guardar transferencia':modalType==='capital'?'Guardar aporte':'Guardar retiro';
  document.getElementById('movementHint').textContent='Escribe el monto en positivo; PASIR aplica el signo automáticamente.';
  document.getElementById('modal').classList.remove('hidden');document.body.style.overflow='hidden';const mb=document.getElementById('modalBody');if(mb)mb.scrollTop=0;setTimeout(()=>document.getElementById('mAmount')?.focus(),60)
}
function switchMovementType(type,forcedAccountName=''){openModal(type,forcedAccountName)}
function closeModal(){document.getElementById('modal').classList.add('hidden');if(document.getElementById('entityModal').classList.contains('hidden'))document.body.style.overflow=''}
function saveMovement(){let amount=Number(document.getElementById('mAmount')?.value);if(!amount||amount<=0)return toast('Ingresa un monto mayor a cero');let currency=document.getElementById('mCurrency')?.value||'PEN',date=document.getElementById('mDate')?.value||todayISO(),time=document.getElementById('mTime')?.value||'',concept=document.getElementById('mConcept')?.value||txLabel({type:modalType}),notes=document.getElementById('mNotes')?.value||'';if(modalType==='transfer'){let from=document.getElementById('mFrom').value,to=document.getElementById('mTo').value;if(from===to)return toast('Selecciona cuentas diferentes');let a=state.accounts.find(x=>x.id===from),b=state.accounts.find(x=>x.id===to);if(!a||!b)return toast('Selecciona cuentas válidas');if(a.currency!==currency||b.currency!==currency)return toast('Origen y destino deben usar la moneda elegida en esta versión');a.balance-=amount;b.balance+=amount;state.transactions.unshift({id:cryptoId(),date,time,type:'transfer',amount,currency,from,to,category:'Transferencia',concept,notes})}else{let account=document.getElementById('mAccount').value,a=state.accounts.find(x=>x.id===account);if(!a)return toast('Selecciona una cuenta');if(a.currency!==currency)return toast('Selecciona la misma moneda de la cuenta');let category=document.getElementById('mCategory')?.value||txLabel({type:modalType});let sign=(modalType==='income'||modalType==='capital')?1:-1;a.balance+=sign*amount;let tx={id:cryptoId(),date,time,type:modalType,amount,currency,account,category,concept,notes};if(modalType==='income'){let courseId=document.getElementById('mCourse')?.value||'',c=state.courses.find(x=>x.id===courseId);tx.courseId=courseId||null;tx.course=c?.name||'';tx.customer=document.getElementById('mCustomer')?.value||'';tx.paymentMethod=document.getElementById('mPayment')?.value||'';tx.operation=document.getElementById('mOperation')?.value||'';if(c&&!document.getElementById('mConcept').value)tx.concept=`Venta — ${c.name}`;if(c)tx.category='Venta de curso'}state.transactions.unshift(tx)}persist();closeModal();toast(modalType==='expense'||modalType==='personal'?'Gasto registrado correctamente':'Movimiento guardado correctamente')}
function deleteTx(id){if(!confirm('¿Eliminar este movimiento? El saldo de la cuenta también será ajustado.'))return;let t=state.transactions.find(x=>x.id===id);if(!t)return;if(t.type==='transfer'){state.accounts.find(a=>a.id===t.from).balance+=t.amount;state.accounts.find(a=>a.id===t.to).balance-=t.amount}else{let a=state.accounts.find(x=>x.id===t.account);let sign=(t.type==='income'||t.type==='capital')?1:-1;a.balance-=sign*t.amount}state.transactions=state.transactions.filter(x=>x.id!==id);persist();toast('Movimiento eliminado')}
function addAccount(){openAccountForm()}
function editAccount(id){openAccountForm(id)}
function openAccountForm(id=null){let a=id?state.accounts.find(x=>x.id===id):null;openEntityModal({eyebrow:'FINANZAS · CUENTAS',title:a?'Editar cuenta':'Nueva cuenta o billetera',subtitle:'Configura dónde está tu dinero. Puedes usar bancos, billeteras, plataformas, efectivo o cripto.',saveLabel:a?'Guardar cambios':'Crear cuenta',body:formSection('▣','Datos de la cuenta',`<div class="form-grid"><div class="field"><label class="required">Nombre</label><input id="fAccountName" value="${esc(a?.name||'')}" placeholder="Ej. Yape, BCP, PayPal"></div><div class="field"><label>Tipo</label><select id="fAccountType">${options(['Banco','Billetera','Efectivo','Plataforma','Cripto','Caja','Otra cuenta'],a?.type||'Billetera')}</select></div><div class="field"><label>Moneda</label><select id="fAccountCurrency" ${a?'disabled':''}>${options(['PEN','USD','USDT'],a?.currency||'PEN')}</select><div class="field-help">La moneda no se cambia después para proteger el historial.</div></div><div class="field"><label>${a?'Saldo actual':'Saldo inicial'}</label><input id="fAccountBalance" type="number" step="0.01" value="${a?.balance??0}"></div><div class="field span-2"><label>Notas</label><textarea id="fAccountNotes" placeholder="Banco, número interno, observaciones...">${esc(a?.notes||'')}</textarea></div></div>`),onSave:()=>{let name=val('fAccountName');if(!name)return toast('Escribe el nombre de la cuenta');let obj={name,type:val('fAccountType'),currency:val('fAccountCurrency')||a?.currency||'PEN',balance:num('fAccountBalance'),notes:val('fAccountNotes')};if(a)Object.assign(a,obj,{currency:a.currency});else state.accounts.push({id:cryptoId(),...obj});persist();closeEntityModal();toast(a?'Cuenta actualizada':'Cuenta creada')}})}
function deleteAccount(id){let a=state.accounts.find(x=>x.id===id);if(!a)return;let used=state.transactions.some(t=>t.account===id||t.from===id||t.to===id);if(used)return alert('Esta cuenta tiene movimientos asociados. Para proteger tu historial no se puede eliminar. Puedes cambiarle el nombre o dejar de usarla.');if(!confirm(`¿Eliminar la cuenta ${a.name}?`))return;state.accounts=state.accounts.filter(x=>x.id!==id);persist();toast('Cuenta eliminada')}
function addCourse(){openCourseForm()}
function editCourse(id){openCourseForm(id)}
function openCourseForm(id=null){let c=id?state.courses.find(x=>x.id===id):null;openEntityModal({eyebrow:'NEGOCIO · CURSOS Y PRODUCTOS',title:c?'Editar curso / producto':'Nuevo curso / producto',subtitle:'Define la información comercial que se utilizará en ventas, metas y rentabilidad.',saveLabel:c?'Guardar cambios':'Crear curso',body:formSection('▰','Información comercial',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre comercial</label><input id="fCourseName" value="${esc(c?.name||'')}" placeholder="Ej. PLC LOGO desde cero"></div><div class="field"><label>Categoría</label><select id="fCourseCategory">${options(['Automatización industrial','PLC','HMI','Variadores de frecuencia','Electricidad industrial','Instrumentación industrial','Software / simulación','Otro'],c?.category||'Automatización industrial')}</select></div><div class="field"><label>Estado</label><select id="fCourseStatus">${options(['Borrador','Publicado','Pausado','Archivado'],c?.status||'Publicado')}</select></div><div class="field"><label class="required">Precio normal (S/)</label><input id="fCoursePrice" type="number" min="0" step="0.01" value="${c?.price??0}"></div><div class="field"><label>Precio promocional (S/)</label><input id="fCoursePromo" type="number" min="0" step="0.01" value="${c?.promo??0}"></div><div class="field"><label>Plataforma de venta</label><select id="fCoursePlatform">${options(['Escuela PASIR','Hotmart','Google Play','Microsoft Store','Venta directa','Otra'],c?.platform||'Escuela PASIR')}</select></div><div class="field"><label>Fecha de lanzamiento</label><input id="fCourseLaunch" type="date" value="${c?.launchDate||todayISO()}"></div><div class="field span-2"><label>Descripción</label><textarea id="fCourseDescription" placeholder="Descripción breve, público objetivo o propuesta de valor">${esc(c?.description||'')}</textarea></div></div>`),hint:'El curso quedará disponible para vincularlo a ventas e ingresos.',onSave:()=>{let name=val('fCourseName'),price=num('fCoursePrice');if(!name)return toast('Escribe el nombre del curso');if(price<0)return toast('Precio no válido');let obj={name,price,promo:num('fCoursePromo'),category:val('fCourseCategory'),status:val('fCourseStatus'),platform:val('fCoursePlatform'),launchDate:val('fCourseLaunch'),description:val('fCourseDescription'),sales:c?.sales||0};if(c)Object.assign(c,obj);else state.courses.push({id:cryptoId(),...obj});persist();closeEntityModal();toast(c?'Curso actualizado':'Curso agregado')}})}
function deleteCourse(id){let c=state.courses.find(x=>x.id===id);if(!c)return;if(!confirm(`¿Eliminar ${c.name}? Esto no elimina movimientos financieros ya registrados.`))return;state.courses=state.courses.filter(x=>x.id!==id);persist();toast('Curso eliminado')}
function addReceivable(){openReceivableForm()}
function editReceivable(id){openReceivableForm(id)}
function openReceivableForm(id=null){let r=id?state.receivables.find(x=>x.id===id):null;openEntityModal({eyebrow:'FINANZAS · CUENTAS POR COBRAR',title:r?'Editar cuenta por cobrar':'Nueva cuenta por cobrar',subtitle:'Registra alumnos o clientes que pagan en cuotas y controla su saldo pendiente.',saveLabel:r?'Guardar cambios':'Registrar deuda',body:formSection('◴','Cliente y compromiso',`<div class="form-grid"><div class="field"><label class="required">Cliente / alumno</label><input id="fRecClient" value="${esc(r?.client||'')}"></div><div class="field"><label>Curso / producto</label><input id="fRecCourse" list="courseNames" value="${esc(r?.course||'')}"><datalist id="courseNames">${state.courses.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist></div><div class="field"><label class="required">Precio total</label><input id="fRecTotal" type="number" min="0" step="0.01" value="${r?.total??0}"></div><div class="field"><label>Monto pagado</label><input id="fRecPaid" type="number" min="0" step="0.01" value="${r?.paid??0}"></div><div class="field"><label>Próxima fecha de pago</label><input id="fRecDue" type="date" value="${r?.due||todayISO()}"></div><div class="field"><label>Número de cuotas</label><input id="fRecInstallments" type="number" min="1" value="${r?.installments||1}"></div><div class="field span-2"><label>Notas</label><textarea id="fRecNotes">${esc(r?.notes||'')}</textarea></div></div>`),onSave:()=>{let client=val('fRecClient'),total=num('fRecTotal'),paid=num('fRecPaid');if(!client)return toast('Escribe el cliente/alumno');if(total<=0)return toast('Ingresa el importe total');let obj={client,course:val('fRecCourse')||'Curso PASIR',total,paid,due:val('fRecDue'),installments:Math.max(1,num('fRecInstallments')||1),notes:val('fRecNotes')};if(r)Object.assign(r,obj);else state.receivables.push({id:cryptoId(),...obj});persist();closeEntityModal();toast(r?'Cuenta por cobrar actualizada':'Cuenta por cobrar registrada')}})}
function deleteReceivable(id){let r=state.receivables.find(x=>x.id===id);if(!r)return;if(!confirm(`¿Eliminar la cuenta por cobrar de ${r.client}?`))return;state.receivables=state.receivables.filter(x=>x.id!==id);persist();toast('Cuenta por cobrar eliminada')}
function addBudget(){openBudgetForm()}
function editBudget(id){openBudgetForm(id)}
function openBudgetForm(id=null){let b=id?state.budgets.find(x=>x.id===id):null;openEntityModal({eyebrow:'NEGOCIO · PRESUPUESTOS',title:b?'Editar presupuesto':'Nuevo presupuesto mensual',subtitle:'Define cuánto quieres permitir por categoría y PASIR comparará automáticamente el gasto real.',saveLabel:b?'Guardar cambios':'Crear presupuesto',body:formSection('◒','Límite de gasto',`<div class="form-grid"><div class="field"><label class="required">Nombre</label><input id="fBudgetName" value="${esc(b?.name||'')}" placeholder="Ej. Publicidad"></div><div class="field"><label class="required">Presupuesto mensual (S/)</label><input id="fBudgetLimit" type="number" min="0" step="0.01" value="${b?.limit??1000}"></div><div class="field span-2"><label>Categoría o palabra a controlar</label><input id="fBudgetMatch" value="${esc(b?.match||'')}" placeholder="Ej. Marketing, Software, Producción"><div class="field-help">PASIR buscará esta palabra dentro de la categoría o concepto de tus gastos.</div></div><div class="field"><label>Aviso preventivo</label><select id="fBudgetAlert"><option value="80" ${(b?.alert||80)==80?'selected':''}>80%</option><option value="90" ${(b?.alert||80)==90?'selected':''}>90%</option><option value="100" ${(b?.alert||80)==100?'selected':''}>100%</option></select></div><div class="field"><label>Estado</label><select id="fBudgetStatus">${options(['Activo','Pausado'],b?.status||'Activo')}</select></div></div>`),hint:'Podrás editar o eliminar este presupuesto cuando quieras.',onSave:()=>{let name=val('fBudgetName'),limit=num('fBudgetLimit');if(!name)return toast('Escribe el nombre del presupuesto');if(limit<=0)return toast('Ingresa un presupuesto mayor a cero');let obj={name,limit,match:val('fBudgetMatch')||name,alert:num('fBudgetAlert')||80,status:val('fBudgetStatus')||'Activo'};if(b)Object.assign(b,obj);else state.budgets.push({id:cryptoId(),...obj});persist();closeEntityModal();toast(b?'Presupuesto actualizado':'Presupuesto creado')}})}
function deleteBudget(id){let b=state.budgets.find(x=>x.id===id);if(!b)return;if(!confirm(`¿Eliminar el presupuesto “${b.name}”?`))return;state.budgets=state.budgets.filter(x=>x.id!==id);persist();toast('Presupuesto eliminado')}
function deleteGoal(id){let g=state.goals.find(x=>x.id===id);if(!g)return;if(!confirm(`¿Eliminar la meta “${g.name}”?`))return;state.goals=state.goals.filter(x=>x.id!==id);persist();toast('Meta eliminada')}

function todayISO(){return new Date().toISOString().slice(0,10)}
function esc(x){return String(x??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]))}
function daysRemaining(date){if(!date)return null;return Math.ceil((new Date(date+'T23:59:59')-new Date())/86400000)}
function defaultStages(){return ['Planificación','Estructura del curso','Creación de módulos','Grabación','Edición','Material complementario','Plataforma','Precio','Página de venta','Publicación','Lanzamiento'].map(name=>({id:cryptoId(),name,status:'Pendiente'}))}
function projectProgress(p){let lessons=(p.modules||[]).flatMap(m=>m.lessons||[]);if(lessons.length){let done=lessons.filter(l=>['Terminada','Publicada'].includes(l.status)).length;return {pct:Math.round(done/lessons.length*100),done,total:lessons.length,label:'lecciones'}}let stages=p.stages||[];let done=stages.filter(x=>x.status==='Completada').length;return {pct:stages.length?Math.round(done/stages.length*100):0,done,total:stages.length,label:'etapas'}}
function projectInvestment(p){return (p.costs||[]).reduce((s,c)=>s+Number(c.amount||0),0)}
function courseByProject(p){return state.courses.find(c=>c.id===p.courseId)||state.courses.find(c=>c.name===p.name)}
function courseRevenue(c){if(!c)return 0;return state.transactions.filter(t=>t.type==='income'&&(t.courseId===c.id||t.course===c.name)).reduce((s,t)=>s+toPen(t.amount,t.currency),0)}
function courseSalesCount(c){if(!c)return 0;return state.transactions.filter(t=>t.type==='income'&&(t.courseId===c.id||t.course===c.name)).length}
function projectRevenue(p){return courseRevenue(courseByProject(p))}
function projectCard(p){let pr=projectProgress(p),days=daysRemaining(p.targetDate);return `<div class="card project-card clickable-card" onclick="openProject('${p.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openProject('${p.id}')}" aria-label="Abrir proyecto ${esc(p.name)}"><div class="split-actions"><span class="pill priority-${p.priority}">${p.priority}</span><span class="status-chip">${p.status}</span></div><h3>${esc(p.name)}</h3><div class="muted" style="font-size:11px">${esc(p.type)}</div><div style="display:flex;justify-content:space-between;margin-top:14px;font-size:12px"><span>Avance</span><b>${pr.pct}%</b></div><div class="progress" style="margin-top:6px"><i style="width:${pr.pct}%"></i></div><div class="project-meta"><div>${pr.label}<b>${pr.done} / ${pr.total}</b></div><div>Fecha objetivo<b>${p.targetDate||'Sin fecha'}</b></div><div>Precio futuro<b>${fmt(p.futurePrice||0)}</b></div><div>Días restantes<b>${days===null?'—':days<0?Math.abs(days)+' atrasado':days}</b></div></div><div class="card-open-hint">Toca la tarjeta para abrir el proyecto →</div><div class="card-actions" onclick="event.stopPropagation()"><button class="btn primary sm" onclick="openProject('${p.id}')">Abrir proyecto</button><button class="btn sm" onclick="editProject('${p.id}')">Editar</button><button class="btn sm" onclick="duplicateProject('${p.id}')">Duplicar</button><button class="btn sm" onclick="archiveProject('${p.id}')">${p.status==='Archivado'?'Reabrir':'Archivar'}</button><button class="btn sm" onclick="deleteProject('${p.id}')">Eliminar</button></div></div>`}
let managementView='goals';
function setManagementView(view){managementView=view==='projects'?'projects':'goals';renderProjects();setTimeout(()=>document.getElementById('managementResults')?.scrollIntoView({behavior:'smooth',block:'start'}),20)}
function renderProjects(){let el=document.getElementById('projectsContent');if(!el)return;let sf=document.getElementById('projectStatusFilter')?.value||'',pf=document.getElementById('projectPriorityFilter')?.value||'',q=(document.getElementById('projectSearch')?.value||'').toLowerCase();let allGoals=state.goals.filter(g=>g.kind!=='financial'),allProjects=state.projects;let goals=allGoals.filter(g=>(!sf||g.status===sf)&&(!pf||g.priority===pf)&&(!q||(g.name+' '+g.category+' '+(g.description||'')).toLowerCase().includes(q)));let projects=allProjects.filter(p=>(!sf||p.status===sf)&&(!pf||p.priority===pf)&&(!q||(p.name+' '+p.type+' '+p.description).toLowerCase().includes(q)));
let goalActive=allGoals.filter(g=>!['Completado','Archivado'].includes(g.status)),goalDone=allGoals.filter(g=>g.status==='Completado'),goalLate=goalActive.filter(g=>g.endDate&&daysRemaining(g.endDate)<0),goalTasks=allGoals.flatMap(g=>g.subtasks||[]).filter(t=>!t.done).length,goalNearest=[...goalActive].filter(g=>g.endDate).sort((a,b)=>String(a.endDate).localeCompare(String(b.endDate)))[0];
let projectActive=allProjects.filter(p=>!['Completado','Publicado','Archivado'].includes(p.status)),projectDone=allProjects.filter(p=>['Completado','Publicado'].includes(p.status)),projectLate=projectActive.filter(p=>p.targetDate&&daysRemaining(p.targetDate)<0),projectTasks=allProjects.flatMap(p=>(p.modules||[]).flatMap(m=>m.lessons||[])).filter(l=>!['Terminada','Publicada'].includes(l.status)).length,projectNearest=[...projectActive].sort((a,b)=>projectProgress(b).pct-projectProgress(a).pct)[0];
let switchHtml=`<div class="management-switch"><button class="management-choice ${managementView==='goals'?'active':''}" onclick="setManagementView('goals')"><span class="management-icon">◎</span><span><b>METAS</b><small>${allGoals.length} registradas · objetivos y subtareas</small></span><strong>${allGoals.length}</strong></button><button class="management-choice ${managementView==='projects'?'active':''}" onclick="setManagementView('projects')"><span class="management-icon">◆</span><span><b>PROYECTOS</b><small>${allProjects.length} registrados · cursos e iniciativas</small></span><strong>${allProjects.length}</strong></button></div>`;
let stats=managementView==='goals'?[['Metas activas',goalActive.length,'En trabajo'],['Metas completadas',goalDone.length,'Finalizadas'],['Metas atrasadas',goalLate.length,'Fuera de fecha'],['Subtareas pendientes',goalTasks,'Acciones por hacer'],['Próxima meta',goalNearest?goalNearest.name:'—',goalNearest?.endDate||'Sin fecha próxima']]:[['Cursos en desarrollo',projectActive.filter(p=>p.type==='Creación de curso').length,'Activos'],['Proyectos terminados',projectDone.length,'Completados/publicados'],['Proyectos atrasados',projectLate.length,'Fuera de fecha'],['Tareas pendientes',projectTasks,'Lecciones por terminar'],['Más próximo',projectNearest?projectNearest.name:'—',projectNearest?projectProgress(projectNearest).pct+'%':'Sin proyectos']];
let statsHtml=`<div class="grid stats management-stats">${stats.map(x=>`<div class="card stat"><div class="label">${x[0]}</div><div class="value" style="font-size:${String(x[1]).length>12?'17px':'26px'}">${esc(x[1])}</div><div class="trend">${esc(x[2])}</div></div>`).join('')}</div>`;
let contentHtml=managementView==='goals'?(goals.length?`<div class="section" id="managementResults"><div class="section-head"><div><h2>Metas</h2><div class="muted" style="font-size:12px;margin-top:4px">Tus metas de gestión están separadas de los proyectos. Toca una tarjeta para entrar.</div></div><span class="pill">${goals.length} visibles</span></div><div class="project-grid">${goals.map(goalCard).join('')}</div></div>`:`<div class="section card empty" id="managementResults"><div class="empty-icon">◎</div>No hay metas con estos filtros. <button class="btn sm" onclick="addAdvancedGoal(false)">＋ Metas</button></div>`):(projects.length?`<div class="section" id="managementResults"><div class="section-head"><div><h2>Proyectos</h2><div class="muted" style="font-size:12px;margin-top:4px">Tus proyectos están separados de las metas. Toca una tarjeta para abrirla.</div></div><span class="pill">${projects.length} visibles</span></div><div class="project-grid">${projects.map(projectCard).join('')}</div></div>`:`<div class="section card empty" id="managementResults"><div class="empty-icon">◆</div>No hay proyectos con estos filtros. <button class="btn sm" onclick="addProject()">＋ Nuevo proyecto</button></div>`);
el.innerHTML=switchHtml+statsHtml+contentHtml;let search=document.getElementById('projectSearch');if(search)search.placeholder=managementView==='goals'?'Buscar meta...':'Buscar proyecto...'}
function renderDevelopment(){let el=document.getElementById('developmentContent');if(!el)return;let list=state.projects.filter(p=>p.type==='Creación de curso'&&!['Publicado','Archivado'].includes(p.status));el.innerHTML=list.length?`<div class="project-grid">${list.map(projectCard).join('')}</div>`:'<div class="card empty"><div class="empty-icon">▰</div>No hay cursos en desarrollo. Crea uno y define sus módulos y lecciones.</div>'}
function addProject(prefillType){openProjectForm(null,prefillType)}
function addCourseProject(){addProject('Creación de curso')}
function editProject(id){openProjectForm(id)}
function openProjectForm(id=null,prefillType=''){let p=id?state.projects.find(x=>x.id===id):null,defaultTarget=new Date(Date.now()+30*86400000).toISOString().slice(0,10);openEntityModal({eyebrow:'GESTIÓN · METAS Y PROYECTOS',title:p?'Editar proyecto':'Nuevo proyecto PASIR',subtitle:'Convierte una idea en un proyecto medible con fechas, prioridad, responsable y objetivo comercial.',saveLabel:p?'Guardar proyecto':'Crear proyecto',body:formSection('◆','Identidad del proyecto',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre del proyecto</label><input id="fProjectName" value="${esc(p?.name||'')}" placeholder="Ej. Curso PLC LOGO desde cero"></div><div class="field"><label>Tipo</label><select id="fProjectType">${options(['Creación de curso','Desarrollo de producto','Contenido','Marketing','Tecnología','Otro'],p?.type||prefillType||'Creación de curso')}</select></div><div class="field"><label>Estado</label><select id="fProjectStatus">${options(['Idea','Planificado','En progreso','Pausado','Bloqueado','En revisión','Completado','Publicado','Archivado'],p?.status||'Planificado')}</select></div><div class="field span-2"><label>Descripción / objetivo</label><textarea id="fProjectDescription" placeholder="Qué quieres construir, para quién y cuál es el resultado esperado">${esc(p?.description||'')}</textarea></div></div>`)+formSection('◷','Planificación',`<div class="form-grid three"><div class="field"><label>Fecha de inicio</label><input id="fProjectStart" type="date" value="${p?.startDate||todayISO()}"></div><div class="field"><label>Fecha objetivo</label><input id="fProjectTarget" type="date" value="${p?.targetDate||defaultTarget}"></div><div class="field"><label>Prioridad</label><select id="fProjectPriority">${options(['Urgente','Alta','Media','Baja'],p?.priority||'Alta')}</select></div><div class="field"><label>Responsable</label><input id="fProjectResponsible" value="${esc(p?.responsible||'Administrador')}"></div><div class="field"><label>Precio futuro (S/)</label><input id="fProjectPrice" type="number" min="0" step="0.01" value="${p?.futurePrice??0}"></div><div class="field"><label>Estado comercial</label><select id="fProjectCommercial"><option>Por definir</option><option>Venta directa</option><option>Hotmart</option><option>Escuela PASIR</option><option>Multiplataforma</option></select></div></div>`),hint:'Si es un curso, después podrás crear módulos, lecciones, costos y publicarlo como producto.',onSave:()=>{let name=val('fProjectName');if(!name)return toast('Escribe el nombre del proyecto');let obj={name,type:val('fProjectType'),status:val('fProjectStatus'),startDate:val('fProjectStart'),targetDate:val('fProjectTarget'),futurePrice:num('fProjectPrice'),responsible:val('fProjectResponsible')||'Administrador',priority:val('fProjectPriority'),description:val('fProjectDescription')};if(p)Object.assign(p,obj);else state.projects.push(normalizeProject({id:cryptoId(),...obj,stages:defaultStages(),modules:[],costs:[]}));persist();closeEntityModal();if(selectedProjectId===id)renderProjectDetail();toast(p?'Proyecto actualizado':'Proyecto creado')}})}
function duplicateProject(id){let p=state.projects.find(x=>x.id===id);if(!p)return;let q=JSON.parse(JSON.stringify(p));q.id=cryptoId();q.name=p.name+' — copia';q.status='Planificado';q.published=false;q.courseId=null;q.stages=q.stages.map(x=>({...x,id:cryptoId()}));q.modules=q.modules.map(m=>({...m,id:cryptoId(),lessons:m.lessons.map(l=>({...l,id:cryptoId()}))}));q.costs=q.costs.map(c=>({...c,id:cryptoId()}));state.projects.push(q);persist();toast('Proyecto duplicado')}
function archiveProject(id){let p=state.projects.find(x=>x.id===id);if(!p)return;p.status=p.status==='Archivado'?'Planificado':'Archivado';persist()}
function deleteProject(id){let p=state.projects.find(x=>x.id===id);if(!p)return;if(p.published&&!confirm('Este proyecto ya fue publicado. El curso publicado no será eliminado. ¿Eliminar solo el proyecto?'))return;if(!p.published&&!confirm(`¿Eliminar el proyecto “${p.name}”?`))return;state.projects=state.projects.filter(x=>x.id!==id);persist();toast('Proyecto eliminado')}
let selectedProjectId=null,projectTab='overview';
function openProject(id){selectedProjectId=id;projectTab='overview';showScreen('project-detail');renderProjectDetail()}
function setProjectTab(tab){projectTab=tab;renderProjectDetail()}
function renderProjectDetail(){let el=document.getElementById('projectDetailContent');if(!el||!selectedProjectId)return;let p=state.projects.find(x=>x.id===selectedProjectId);if(!p){el.innerHTML='<div class="card empty">Proyecto no encontrado.</div>';return}let pr=projectProgress(p),days=daysRemaining(p.targetDate),invest=projectInvestment(p),rev=projectRevenue(p),profit=rev-invest,roi=invest?Math.round(profit/invest*100):0;let tabs=[['overview','Resumen'],['stages','Etapas'],['modules','Módulos y lecciones'],['costs','Costos y ROI'],['notes','Notas']];el.innerHTML=`<div class="split-actions"><button class="btn" onclick="showScreen('projects')">← Volver</button><div class="quick"><button class="btn" onclick="editProject('${p.id}');renderProjectDetail()">Editar</button>${!p.published?`<button class="btn good" onclick="publishProject('${p.id}')">FINALIZAR Y PUBLICAR CURSO</button>`:'<span class="pill">✓ Curso publicado</span>'}</div></div><div class="detail-hero section"><div class="card"><div class="split-actions"><div><span class="pill priority-${p.priority}">${p.priority}</span><h1 style="margin:10px 0 4px">${esc(p.name)}</h1><div class="muted">${esc(p.type)} · ${esc(p.status)}</div></div><div style="text-align:right"><div class="muted" style="font-size:11px">AVANCE GENERAL</div><div style="font-size:36px;font-weight:900">${pr.pct}%</div></div></div><div class="progress" style="height:12px;margin-top:18px"><i style="width:${pr.pct}%"></i></div><div class="metric-row" style="margin-top:14px"><div class="metric-box"><span class="muted">Módulos</span><div class="n">${p.modules.length}</div></div><div class="metric-box"><span class="muted">Lecciones</span><div class="n">${p.modules.flatMap(m=>m.lessons).length}</div></div><div class="metric-box"><span class="muted">Fecha objetivo</span><div class="n" style="font-size:15px">${p.targetDate||'—'}</div></div><div class="metric-box"><span class="muted">Días restantes</span><div class="n">${days===null?'—':days}</div></div></div></div><div class="card"><div class="label muted">ECONOMÍA DEL CURSO</div><div class="metric-box" style="margin-top:10px"><span class="muted">Inversión</span><div class="n">${fmt(invest)}</div></div><div class="metric-box" style="margin-top:8px"><span class="muted">Ventas acumuladas</span><div class="n">${fmt(rev)}</div></div><div class="metric-box" style="margin-top:8px"><span class="muted">Utilidad / ROI</span><div class="n">${fmt(profit)} · ${roi}%</div></div></div></div><div class="tabs">${tabs.map(t=>`<button class="tab ${projectTab===t[0]?'active':''}" onclick="setProjectTab('${t[0]}')">${t[1]}</button>`).join('')}</div><div id="projectTabBody">${renderProjectTab(p)}</div>`}
function renderProjectTab(p){if(projectTab==='stages')return renderStagesTab(p);if(projectTab==='modules')return renderModulesTab(p);if(projectTab==='costs')return renderCostsTab(p);if(projectTab==='notes')return renderNotesTab(p);let pr=projectProgress(p);return `<div class="grid cols"><div class="card"><h2 style="margin-top:0">Resumen del proyecto</h2><div class="goal-desc">${esc(p.description||'Agrega una descripción del objetivo, alcance y propuesta del curso desde Editar.')}</div><div class="info-strip" style="margin-top:14px"><span class="pill">Responsable: ${esc(p.responsible)}</span><span class="pill">Inicio: ${p.startDate}</span><span class="pill">Precio futuro: ${fmt(p.futurePrice)}</span></div></div><div class="card"><h2 style="margin-top:0">Siguiente paso</h2><div class="insight">${nextProjectAction(p)}</div><div class="card-actions"><button class="btn primary sm" onclick="setProjectTab('${p.modules.length?'modules':'stages'}')">Trabajar ahora</button></div></div></div>`}
function nextProjectAction(p){let l=p.modules.flatMap(m=>m.lessons).find(x=>!['Terminada','Publicada'].includes(x.status));if(l)return`Continúa con la lección <b>${esc(l.name)}</b> (${l.status}).`;let st=p.stages.find(x=>x.status!=='Completada');if(st)return`Completa la etapa <b>${esc(st.name)}</b>.`;return p.published?'El curso ya está publicado y conectado con Ventas y Finanzas.':'El contenido está listo. Puedes finalizar y publicar el curso.'}
function renderStagesTab(p){return `<div class="card"><div class="section-head"><h2>Etapas de creación</h2><button class="btn sm" onclick="addStage('${p.id}')">＋ Etapa</button></div>${p.stages.map(st=>`<div class="stage-row"><div><b>${esc(st.name)}</b></div><select class="select-sm" onchange="setStageStatus('${p.id}','${st.id}',this.value)">${['Pendiente','En progreso','Completada','Bloqueada'].map(x=>`<option ${st.status===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')||'<div class="empty">Sin etapas.</div>'}</div>`}
function addStage(pid){let p=state.projects.find(x=>x.id===pid);if(!p)return;openEntityModal({eyebrow:'PROYECTO · ETAPAS',title:'Nueva etapa del proyecto',subtitle:`Agrega una etapa personalizada a ${p.name}.`,saveLabel:'Agregar etapa',body:formSection('◆','Etapa',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre de la etapa</label><input id="fStageName" placeholder="Ej. Validación con alumnos"></div><div class="field"><label>Estado inicial</label><select id="fStageStatus">${options(['Pendiente','En progreso','Completada','Bloqueada'],'Pendiente')}</select></div><div class="field"><label>Orden</label><input id="fStageOrder" type="number" min="1" value="${p.stages.length+1}"></div></div>`),onSave:()=>{let name=val('fStageName');if(!name)return toast('Escribe el nombre de la etapa');p.stages.push({id:cryptoId(),name,status:val('fStageStatus')||'Pendiente',order:num('fStageOrder')||p.stages.length+1});persist();closeEntityModal();renderProjectDetail();toast('Etapa agregada')}})}
function setStageStatus(pid,sid,status){let p=state.projects.find(x=>x.id===pid),st=p?.stages.find(x=>x.id===sid);if(st){st.status=status;persist();renderProjectDetail()}}
function renderModulesTab(p){return `<div class="card"><div class="section-head"><div><h2>Módulos y lecciones</h2><div class="muted" style="font-size:11px">El avance general se calcula con las lecciones terminadas/publicadas.</div></div><button class="btn primary sm" onclick="addModule('${p.id}')">＋ Módulo</button></div>${p.modules.map((m,i)=>`<div class="module"><div class="module-head"><div><b>Módulo ${i+1}: ${esc(m.name)}</b><div class="muted" style="font-size:10px">${m.lessons.filter(l=>['Terminada','Publicada'].includes(l.status)).length}/${m.lessons.length} lecciones terminadas</div></div><div><button class="btn sm" onclick="addLesson('${p.id}','${m.id}')">＋ Lección</button> <button class="btn sm" onclick="deleteModule('${p.id}','${m.id}')">Eliminar</button></div></div><div class="module-body">${m.lessons.map(l=>`<div class="lesson-row"><div>${esc(l.name)}</div><select class="select-sm" onchange="setLessonStatus('${p.id}','${m.id}','${l.id}',this.value)">${['Pendiente','Guion preparado','Grabada','Editándose','Terminada','Publicada'].map(x=>`<option ${l.status===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')||'<div class="empty" style="padding:15px">Sin lecciones.</div>'}</div></div>`).join('')||'<div class="empty">Aún no has creado módulos.</div>'}</div>`}
function addModule(pid){let p=state.projects.find(x=>x.id===pid);if(!p)return;openEntityModal({eyebrow:'PRODUCCIÓN DEL CURSO',title:'Nuevo módulo',subtitle:`Agrega un bloque de contenido a ${p.name}.`,saveLabel:'Crear módulo',body:formSection('▰','Módulo',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre del módulo</label><input id="fModuleName" placeholder="Ej. Programación básica"></div><div class="field"><label>Número / orden</label><input id="fModuleOrder" type="number" min="1" value="${p.modules.length+1}"></div><div class="field"><label>Estado inicial</label><select id="fModuleStatus"><option>Planificado</option><option>En progreso</option></select></div></div>`),onSave:()=>{let name=val('fModuleName');if(!name)return toast('Escribe el nombre del módulo');p.modules.push({id:cryptoId(),name,order:num('fModuleOrder')||p.modules.length+1,status:val('fModuleStatus'),lessons:[]});persist();closeEntityModal();renderProjectDetail();toast('Módulo creado')}})}
function deleteModule(pid,mid){let p=state.projects.find(x=>x.id===pid);if(!p||!confirm('¿Eliminar este módulo y todas sus lecciones?'))return;p.modules=p.modules.filter(x=>x.id!==mid);persist();renderProjectDetail()}
function addLesson(pid,mid){let p=state.projects.find(x=>x.id===pid),m=p?.modules.find(x=>x.id===mid);if(!m)return;openEntityModal({eyebrow:'PRODUCCIÓN · LECCIONES',title:'Nueva lección',subtitle:`Agrega una lección dentro de ${m.name}.`,saveLabel:'Crear lección',body:formSection('▶','Contenido',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre de la lección</label><input id="fLessonName" placeholder="Ej. Temporizadores TON y TOF"></div><div class="field"><label>Estado</label><select id="fLessonStatus">${options(['Pendiente','Guion preparado','Grabada','Editándose','Terminada','Publicada'],'Pendiente')}</select></div><div class="field"><label>Duración estimada (min)</label><input id="fLessonDuration" type="number" min="0" value="0"></div><div class="field span-2"><label>Objetivo / nota</label><textarea id="fLessonNote" placeholder="Qué debe aprender el alumno"></textarea></div></div>`),onSave:()=>{let name=val('fLessonName');if(!name)return toast('Escribe el nombre de la lección');m.lessons.push({id:cryptoId(),name,status:val('fLessonStatus'),duration:num('fLessonDuration'),note:val('fLessonNote')});persist();closeEntityModal();renderProjectDetail();toast('Lección creada')}})}
function setLessonStatus(pid,mid,lid,status){let p=state.projects.find(x=>x.id===pid),m=p?.modules.find(x=>x.id===mid),l=m?.lessons.find(x=>x.id===lid);if(l){l.status=status;persist();renderProjectDetail()}}
function renderCostsTab(p){let inv=projectInvestment(p),rev=projectRevenue(p),profit=rev-inv,roi=inv?Math.round(profit/inv*100):0,price=courseByProject(p)?.price||p.futurePrice||0,be=price?Math.ceil(inv/price):0;return `<div class="grid cols"><div class="card"><div class="section-head"><h2>Costos de producción</h2><button class="btn primary sm" onclick="addProjectCost('${p.id}')">＋ Registrar costo</button></div>${p.costs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Categoría</th><th>Monto</th><th>Nota</th><th></th></tr></thead><tbody>${p.costs.map(c=>`<tr><td>${esc(c.category)}</td><td>${fmt(c.amount)}</td><td>${esc(c.note||'')}</td><td><button class="btn sm" onclick="deleteProjectCost('${p.id}','${c.id}')">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aún no registraste costos de producción.</div>'}</div><div class="card"><h2 style="margin-top:0">Rentabilidad</h2><div class="metric-box"><span class="muted">Total inversión</span><div class="n">${fmt(inv)}</div></div><div class="metric-box" style="margin-top:8px"><span class="muted">Ventas acumuladas</span><div class="n">${fmt(rev)}</div></div><div class="metric-box" style="margin-top:8px"><span class="muted">Utilidad generada</span><div class="n">${fmt(profit)}</div></div><div class="metric-box" style="margin-top:8px"><span class="muted">ROI</span><div class="n">${roi}%</div></div><div class="note" style="margin-top:12px">Punto de equilibrio: <b>${be} ventas</b> a un precio de ${fmt(price)}.</div></div></div>`}
function addProjectCost(pid){let p=state.projects.find(x=>x.id===pid);if(!p)return;openEntityModal({eyebrow:'RENTABILIDAD · PRODUCCIÓN',title:'Registrar costo del proyecto',subtitle:`Este costo se sumará a la inversión de ${p.name}.`,saveLabel:'Registrar costo',body:formSection('S/','Costo de producción',`<div class="form-grid"><div class="field"><label class="required">Categoría</label><select id="fCostCategory">${options(['Edición','Publicidad','Diseño','Software','Profesor','Equipos','Material educativo','Plataforma','Otro'],'Edición')}</select></div><div class="field"><label class="required">Monto (S/)</label><input id="fCostAmount" type="number" min="0" step="0.01"></div><div class="field"><label>Fecha</label><input id="fCostDate" type="date" value="${todayISO()}"></div><div class="field"><label>Proveedor / responsable</label><input id="fCostProvider"></div><div class="field span-2"><label>Nota</label><textarea id="fCostNote"></textarea></div></div>`),onSave:()=>{let amount=num('fCostAmount');if(amount<=0)return toast('Ingresa un monto mayor a cero');p.costs.push({id:cryptoId(),category:val('fCostCategory'),amount,note:val('fCostNote'),provider:val('fCostProvider'),date:val('fCostDate')||todayISO()});persist();closeEntityModal();renderProjectDetail();toast('Costo registrado')}})}
function deleteProjectCost(pid,cid){let p=state.projects.find(x=>x.id===pid);if(!p)return;p.costs=p.costs.filter(x=>x.id!==cid);persist();renderProjectDetail()}
function renderNotesTab(p){return `<div class="card"><div class="section-head"><h2>Notas del proyecto</h2><button class="btn sm" onclick="editProjectNotes('${p.id}')">Editar notas</button></div><div style="white-space:pre-wrap;line-height:1.6">${esc(p.notes||'Sin notas todavía.')}</div></div>`}
function editProjectNotes(pid){let p=state.projects.find(x=>x.id===pid);if(!p)return;openEntityModal({eyebrow:'PROYECTO · NOTAS',title:'Notas del proyecto',subtitle:'Guarda decisiones, pendientes, enlaces o información de contexto.',saveLabel:'Guardar notas',body:formSection('✎','Notas',`<div class="field"><textarea id="fProjectNotes" style="min-height:220px" placeholder="Escribe aquí...">${esc(p.notes||'')}</textarea></div>`),onSave:()=>{p.notes=val('fProjectNotes');persist();closeEntityModal();renderProjectDetail();toast('Notas guardadas')}})}
function publishProject(pid){let p=state.projects.find(x=>x.id===pid);if(!p)return;let existing=courseByProject(p);openEntityModal({eyebrow:'LANZAMIENTO · PUBLICACIÓN',title:'Finalizar y publicar curso',subtitle:'Convierte este proyecto en un producto PASIR conectado con Ventas, Ingresos y Rentabilidad.',saveLabel:'Publicar curso',saveClass:'good',body:formSection('✓','Datos comerciales',`<div class="modal-chip-row"><span class="modal-chip">Proyecto: ${esc(p.name)}</span><span class="modal-chip">Avance: ${projectProgress(p).pct}%</span><span class="modal-chip">Inversión: ${fmt(projectInvestment(p))}</span></div><div class="form-grid"><div class="field span-2"><label class="required">Nombre comercial</label><input id="fPubName" value="${esc(existing?.name||p.name)}"></div><div class="field"><label class="required">Precio</label><input id="fPubPrice" type="number" min="0" step="0.01" value="${existing?.price??p.futurePrice??0}"></div><div class="field"><label>Precio promocional</label><input id="fPubPromo" type="number" min="0" step="0.01" value="${existing?.promo??0}"></div><div class="field"><label>Categoría</label><input id="fPubCategory" value="${esc(existing?.category||'Automatización industrial')}"></div><div class="field"><label>Plataforma</label><select id="fPubPlatform">${options(['Escuela PASIR','Hotmart','Google Play','Microsoft Store','Venta directa','Multiplataforma'],existing?.platform||'Escuela PASIR')}</select></div><div class="field"><label>Fecha de lanzamiento</label><input id="fPubDate" type="date" value="${existing?.launchDate||todayISO()}"></div><div class="field"><label>Estado</label><select id="fPubStatus"><option>Publicado</option></select></div><div class="field span-2"><label>Descripción</label><textarea id="fPubDesc">${esc(existing?.description||p.description||'')}</textarea></div></div>`),hint:'Al publicar, el curso aparecerá automáticamente al registrar nuevas ventas.',onSave:()=>{let name=val('fPubName'),price=num('fPubPrice');if(!name)return toast('Escribe el nombre comercial');let c=existing;if(c)Object.assign(c,{name,price,promo:num('fPubPromo'),category:val('fPubCategory'),platform:val('fPubPlatform'),launchDate:val('fPubDate'),description:val('fPubDesc'),status:'Publicado'});else{c={id:cryptoId(),name,price,promo:num('fPubPromo'),category:val('fPubCategory'),platform:val('fPubPlatform'),launchDate:val('fPubDate'),description:val('fPubDesc'),status:'Publicado',sales:0};state.courses.push(c)}p.courseId=c.id;p.published=true;p.status='Publicado';p.futurePrice=price;p.launchDate=val('fPubDate');p.stages.forEach(st=>{if(['Publicación','Lanzamiento'].includes(st.name))st.status='Completada'});persist();closeEntityModal();renderProjectDetail();toast('Curso publicado y conectado con Ventas e Ingresos')}})}
let selectedGoalId=null;
function openGoal(id){selectedGoalId=id;showScreen('goal-detail');renderGoalDetail()}
function goalBack(){let g=state.goals.find(x=>x.id===selectedGoalId);if(g?.kind==='financial'){showScreen('goals')}else{managementView='goals';showScreen('projects')}}
function renderGoalDetail(){let el=document.getElementById('goalDetailContent');if(!el||!selectedGoalId)return;let g=state.goals.find(x=>x.id===selectedGoalId);if(!g){el.innerHTML='<div class="card empty">Meta no encontrada.</div>';return}let cur=goalCurrent(g),pct=g.kind==='financial'?(g.target?Math.max(0,Math.min(100,Math.round(cur/g.target*100))):0):Math.round(cur),days=daysRemaining(g.endDate),done=(g.subtasks||[]).filter(t=>t.done).length,total=(g.subtasks||[]).length;let currentLabel=g.kind==='financial'?(g.metric.includes('sales')?`${Math.round(cur)} / ${g.target}`:`${fmt(cur)} / ${fmt(g.target)}`):`${pct}%`;let detail=g.kind==='financial'?`<div class="grid cols"><div class="card"><h2 style="margin-top:0">Seguimiento automático</h2><div class="metric-row"><div class="metric-box"><span class="muted">Actual</span><div class="n">${currentLabel}</div></div><div class="metric-box"><span class="muted">Avance</span><div class="n">${pct}%</div></div><div class="metric-box"><span class="muted">Inicio</span><div class="n" style="font-size:15px">${g.startDate||'—'}</div></div><div class="metric-box"><span class="muted">Fin</span><div class="n" style="font-size:15px">${g.endDate||'—'}</div></div></div><div class="projection">${goalProjection(g,cur)}</div></div><div class="card"><h2 style="margin-top:0">Clasificación</h2><div class="info-strip"><span class="pill">${goalTypeLabel(g.metric)}</span><span class="pill">${goalPeriodLabel(g.period)}</span><span class="pill priority-${g.priority}">${g.priority}</span></div><div class="goal-desc">${esc(g.description||'Sin descripción.')}</div></div></div>`:`<div class="grid cols"><div class="card"><div class="section-head"><h2>Subtareas de la meta</h2><button class="btn primary sm" onclick="addGoalSubtask('${g.id}')">＋ Subtarea</button></div>${total?`<div>${g.subtasks.map(t=>`<div class="task-row"><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" ${t.done?'checked':''} onchange="toggleGoalTask('${g.id}','${t.id}')"> <span style="${t.done?'text-decoration:line-through;opacity:.65':''}">${esc(t.name)}</span></label><span class="pill">${t.due||'Sin fecha'}</span></div>`).join('')}</div>`:'<div class="empty">Todavía no has agregado subtareas.</div>'}</div><div class="card"><h2 style="margin-top:0">Información de la meta</h2><div class="metric-row" style="grid-template-columns:1fr 1fr"><div class="metric-box"><span class="muted">Subtareas</span><div class="n">${done}/${total}</div></div><div class="metric-box"><span class="muted">Días restantes</span><div class="n">${days===null?'—':days}</div></div></div><div class="goal-desc" style="margin-top:14px">${esc(g.description||'Sin descripción.')}</div></div></div>`;el.innerHTML=`<div class="split-actions"><button class="btn" onclick="goalBack()">← Volver a ${g.kind==='financial'?'Metas financieras':'Metas'}</button><div class="quick"><button class="btn" onclick="editAdvancedGoal('${g.id}')">Editar</button><button class="btn" onclick="duplicateGoal('${g.id}')">Duplicar</button><button class="btn" onclick="toggleGoalPause('${g.id}')">${g.status==='Pausado'?'Reabrir':'Pausar'}</button><button class="btn good" onclick="completeGoal('${g.id}')">Completar</button></div></div><div class="card detail-goal-hero section"><div class="split-actions"><div><span class="pill priority-${g.priority}">${g.priority}</span><h1 style="margin:10px 0 4px">${esc(g.name)}</h1><div class="muted">${g.kind==='financial'?goalTypeLabel(g.metric):g.category} · ${g.status}</div></div><div style="text-align:right"><div class="muted" style="font-size:11px">AVANCE</div><div style="font-size:38px;font-weight:900">${pct}%</div></div></div><div class="progress" style="height:12px;margin-top:18px"><i style="width:${pct}%"></i></div></div>${detail}<div class="card-actions"><button class="btn" onclick="resetGoal('${g.id}')">Reiniciar</button><button class="btn bad" onclick="if(confirm('¿Eliminar esta meta?')){state.goals=state.goals.filter(x=>x.id!=='${g.id}');persist();goalBack()}">Eliminar meta</button></div>`}

function addAdvancedGoal(financial=true){openGoalForm(null,financial)}
function addGoal(){addAdvancedGoal(true)}
function editAdvancedGoal(id){let g=state.goals.find(x=>x.id===id);if(g)openGoalForm(id,g.kind==='financial')}
function openGoalForm(id=null,financial=true){let g=id?state.goals.find(x=>x.id===id):null,isFinancial=g?g.kind==='financial':financial;let definition=formSection('◎','Definición de la meta',`<div class="form-grid"><div class="field span-2"><label class="required">Nombre de la meta</label><input id="fGoalName" value="${esc(g?.name||'')}" placeholder="${isFinancial?'Ej. Facturar S/ 15,000 en septiembre':'Ej. Terminar curso PLC LOGO'}"></div><div class="field"><label>Tipo</label><input value="${isFinancial?'Meta financiera':'Meta de gestión'}" disabled><input id="fGoalKind" type="hidden" value="${isFinancial?'financial':'business'}"></div><div class="field"><label>Prioridad</label><select id="fGoalPriority">${options(['Urgente','Alta','Media','Baja'],g?.priority||'Alta')}</select></div><div class="field span-2"><label>Descripción / notas</label><textarea id="fGoalDescription" placeholder="${isFinancial?'Describe el objetivo financiero y su contexto.':'Describe qué quieres conseguir y el resultado esperado.'}">${esc(g?.description||'')}</textarea></div></div>`);let measurement=isFinancial?formSection('S/','Medición automática',`<div class="form-grid"><div class="field"><label>Métrica</label><select id="fGoalMetric">${options([['income','Ingresos'],['profit','Utilidad'],['sales','Número de ventas'],['course_sales','Ventas de un curso'],['course_revenue','Facturación de un curso']],g?.metric||'income')}</select></div><div class="field"><label>Periodo</label><select id="fGoalPeriod" onchange="syncGoalDates()">${options([['daily','Diaria'],['weekly','Semanal'],['monthly','Mensual'],['quarterly','Trimestral'],['annual','Anual'],['custom','Personalizada']],g?.period||'monthly')}</select></div><div class="field"><label class="required">Objetivo</label><input id="fGoalTarget" type="number" min="0" step="0.01" value="${g?.target??15000}"></div><div class="field"><label>Curso (si aplica)</label><select id="fGoalCourse"><option value="">Todos / no aplica</option>${state.courses.map(c=>`<option value="${c.id}" ${g?.courseId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>`):'';let categories=isFinancial?['Finanzas','Ventas','Curso / producto','Otra']:['Negocio','Creación de cursos','Contenido','Marketing','Tecnología','Personal','Otra'];let dates=formSection('◷','Periodo y clasificación',`<div class="form-grid"><div class="field"><label>Fecha inicio</label><input id="fGoalStart" type="date" value="${g?.startDate||periodStart(isFinancial?(g?.period||'monthly'):'custom')}"></div><div class="field"><label>Fecha final</label><input id="fGoalEnd" type="date" value="${g?.endDate||periodEnd(isFinancial?(g?.period||'monthly'):'custom')}"></div><div class="field"><label>Categoría</label><select id="fGoalCategory">${options(categories,g?.category||(isFinancial?'Finanzas':'Negocio'))}</select></div><div class="field"><label>Estado</label><select id="fGoalStatus">${options(['Idea','Planificado','En progreso','Pausado','Bloqueado','En revisión','Completado','Archivado'],g?.status||'En progreso')}</select></div></div>`);openEntityModal({eyebrow:isFinancial?'NEGOCIO · METAS FINANCIERAS':'GESTIÓN · METAS',title:g?'Editar meta':isFinancial?'Nueva meta financiera':'Nueva meta',subtitle:isFinancial?'Define un objetivo numérico que PASIR actualizará automáticamente con tus movimientos reales.':'Define un objetivo de gestión con fecha, prioridad y subtareas, separado de tus proyectos.',saveLabel:g?'Guardar cambios':'Crear meta',body:definition+measurement+dates,hint:isFinancial?'El avance se calcula automáticamente; no necesitas actualizar el monto manualmente.':'Después de crearla podrás abrir su tarjeta y agregar subtareas.',onSave:()=>{let name=val('fGoalName');if(!name)return toast('Escribe el nombre de la meta');let period=isFinancial?(val('fGoalPeriod')||'monthly'):'custom';let obj={name,kind:isFinancial?'financial':'business',metric:isFinancial?(val('fGoalMetric')||'income'):'progress',period,target:isFinancial?num('fGoalTarget'):100,startDate:val('fGoalStart'),endDate:val('fGoalEnd'),priority:val('fGoalPriority'),category:val('fGoalCategory'),description:val('fGoalDescription'),status:val('fGoalStatus'),courseId:isFinancial?(val('fGoalCourse')||null):null,subtasks:g?.subtasks||[]};if(g)Object.assign(g,obj);else state.goals.push(normalizeGoal({id:cryptoId(),...obj}));persist();closeEntityModal();toast(g?'Meta actualizada':'Meta creada')}})}
function toggleGoalFormFields(){let financial=val('fGoalKind')==='financial',box=document.getElementById('goalFinancialFields');if(box)box.classList.toggle('hidden',!financial)}
function syncGoalDates(){let p=val('fGoalPeriod');if(!p||p==='custom')return;let a=document.getElementById('fGoalStart'),b=document.getElementById('fGoalEnd');if(a)a.value=periodStart(p);if(b)b.value=periodEnd(p)}
function editGoal(id){editAdvancedGoal(id)}
function duplicateGoal(id){let g=state.goals.find(x=>x.id===id);if(!g)return;let q=JSON.parse(JSON.stringify(g));q.id=cryptoId();q.name=g.name+' — copia';q.status='En progreso';q.subtasks=q.subtasks.map(t=>({...t,id:cryptoId()}));state.goals.push(q);persist()}
function toggleGoalPause(id){let g=state.goals.find(x=>x.id===id);if(!g)return;g.status=g.status==='Pausado'?'En progreso':'Pausado';persist()}
function completeGoal(id){let g=state.goals.find(x=>x.id===id);if(!g)return;g.status='Completado';persist()}
function resetGoal(id){let g=state.goals.find(x=>x.id===id);if(!g)return;g.status='En progreso';if(g.kind!=='financial')g.subtasks.forEach(t=>t.done=false);persist()}
function addGoalSubtask(id){let g=state.goals.find(x=>x.id===id);if(!g)return;openEntityModal({eyebrow:'META · SUBTAREAS',title:'Nueva subtarea',subtitle:`Divide “${g.name}” en acciones concretas.`,saveLabel:'Agregar subtarea',body:formSection('✓','Acción',`<div class="form-grid"><div class="field span-2"><label class="required">Subtarea</label><input id="fGoalTaskName" placeholder="Ej. Diseñar portada del curso"></div><div class="field"><label>Fecha objetivo</label><input id="fGoalTaskDue" type="date" value="${g.endDate||todayISO()}"></div><div class="field"><label>Prioridad</label><select id="fGoalTaskPriority">${options(['Alta','Media','Baja'],'Media')}</select></div></div>`),onSave:()=>{let name=val('fGoalTaskName');if(!name)return toast('Escribe la subtarea');g.subtasks.push({id:cryptoId(),name,done:false,due:val('fGoalTaskDue'),priority:val('fGoalTaskPriority')});persist();closeEntityModal();toast('Subtarea agregada')}})}
function toggleGoalTask(gid,tid){let g=state.goals.find(x=>x.id===gid),t=g?.subtasks.find(x=>x.id===tid);if(t){t.done=!t.done;persist()}}
function renderNonFinancialGoals(){return state.goals.filter(g=>g.kind!=='financial').map(g=>goalCard(g)).join('')}

function addPayable(){openPayableForm()}
function openPayableForm(){openEntityModal({eyebrow:'FINANZAS · CUENTAS POR PAGAR',title:'Nueva cuenta por pagar',subtitle:'Registra obligaciones futuras para anticipar la liquidez real del negocio.',saveLabel:'Registrar compromiso',body:formSection('◷','Compromiso de pago',`<div class="form-grid"><div class="field"><label class="required">Proveedor / beneficiario</label><input id="fPayProvider"></div><div class="field"><label>Servicio / concepto</label><input id="fPayService"></div><div class="field"><label class="required">Monto (S/)</label><input id="fPayAmount" type="number" min="0" step="0.01"></div><div class="field"><label>Fecha límite</label><input id="fPayDue" type="date" value="${todayISO()}"></div><div class="field"><label>Categoría</label><select id="fPayCategory">${options(['Software','Marketing','Producción','Personal','Impuestos','Servicios','Proveedor','Otro'],'Servicios')}</select></div><div class="field"><label>Estado</label><select id="fPayStatus"><option>Pendiente</option><option>Programado</option></select></div><div class="field span-2"><label>Notas</label><textarea id="fPayNotes"></textarea></div></div>`),onSave:()=>{let provider=val('fPayProvider'),amount=num('fPayAmount');if(!provider)return toast('Escribe el proveedor o beneficiario');if(amount<=0)return toast('Ingresa un monto mayor a cero');state.payables.push({id:cryptoId(),provider,service:val('fPayService'),amount,due:val('fPayDue'),category:val('fPayCategory'),status:val('fPayStatus')||'Pendiente',notes:val('fPayNotes')});persist();closeEntityModal();toast('Cuenta por pagar registrada')}})}
function markPayable(id){let p=state.payables.find(x=>x.id===id);if(!p)return;p.status=p.status==='Pagado'?'Pendiente':'Pagado';persist()}
function deletePayable(id){if(!confirm('¿Eliminar este compromiso?'))return;state.payables=state.payables.filter(x=>x.id!==id);persist()}
function renderPayables(){let el=document.getElementById('payablesContent');if(!el)return;let pending=state.payables.filter(x=>x.status!=='Pagado').reduce((s,x)=>s+x.amount,0),rows=state.payables.map(p=>`<tr><td>${esc(p.provider)}</td><td>${esc(p.service)}</td><td>${fmt(p.amount)}</td><td>${p.due||'—'}</td><td><span class="status-chip">${p.status}</span></td><td><button class="btn sm" onclick="markPayable('${p.id}')">${p.status==='Pagado'?'Reabrir':'Marcar pagado'}</button> <button class="btn sm" onclick="deletePayable('${p.id}')">Eliminar</button></td></tr>`).join('');el.innerHTML=`<div class="card stat" style="margin-bottom:14px"><div class="label">Total pendiente por pagar</div><div class="value">${fmt(pending)}</div></div>${rows?`<div class="table-wrap"><table class="table"><thead><tr><th>Proveedor</th><th>Concepto</th><th>Monto</th><th>Vence</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="card empty">No hay cuentas por pagar.</div>'}`}


function commercialCourse(p){return p?.courseId?state.courses.find(c=>c.id===p.courseId):null}
function commercialName(p){return commercialCourse(p)?.name||p?.productName||'Producto PASIR'}
function commercialPrice(p){let c=commercialCourse(p);return p?.priceText||(c?(c.promo>0?`${fmt(c.promo)} (promoción) · Normal ${fmt(c.price)}`:fmt(c.price)):'')}
function commercialCompletion(p){let keys=['shortMessage','fullMessage','syllabus','benefits','requirements','priceText','paymentMethods','faq','closing','link'];let filled=keys.filter(k=>String(p?.[k]||'').trim()).length;return {filled,total:keys.length,pct:Math.round(filled/keys.length*100)}}
function commercialText(p,key){if(!p)return'';if(key==='priceText')return commercialPrice(p);return String(p[key]||'')}
function clipboardFallback(text){let ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}document.body.removeChild(ta);return ok}
async function copyText(text,label='Información'){text=String(text||'').trim();if(!text)return toast('No hay contenido para copiar');let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);ok=true}else ok=clipboardFallback(text)}catch(e){ok=clipboardFallback(text)}toast(ok?`${label} copiado`:'No se pudo copiar automáticamente')}
function copyCommercialField(id,key,label='Información'){let p=state.commercialProfiles.find(x=>x.id===id);if(!p)return;copyText(commercialText(p,key),label)}
function buildCommercialAll(p){let c=commercialCourse(p),name=commercialName(p),parts=[];parts.push(name);let price=commercialPrice(p);if(price)parts.push(`Precio: ${price}`);if(p.modality)parts.push(`Modalidad: ${p.modality}`);if(p.duration)parts.push(`Duración: ${p.duration}`);if(p.level)parts.push(`Nivel: ${p.level}`);if(p.audience)parts.push(`Dirigido a: ${p.audience}`);if(p.shortMessage)parts.push(`Mensaje breve:\n${p.shortMessage}`);if(p.fullMessage)parts.push(`Información completa:\n${p.fullMessage}`);if(p.syllabus)parts.push(`Temario / contenido:\n${p.syllabus}`);if(p.benefits)parts.push(`Beneficios:\n${p.benefits}`);if(p.requirements)parts.push(`Requisitos:\n${p.requirements}`);if(p.paymentMethods)parts.push(`Medios de pago:\n${p.paymentMethods}`);if(p.certificate)parts.push(`Certificado: ${p.certificate}`);if(p.faq)parts.push(`Preguntas frecuentes:\n${p.faq}`);if(p.closing)parts.push(`Cierre / llamada a la acción:\n${p.closing}`);if(p.link)parts.push(`Enlace: ${p.link}`);return parts.filter(Boolean).join('\n\n')}
function copyCommercialAll(id){let p=state.commercialProfiles.find(x=>x.id===id);if(p)copyText(buildCommercialAll(p),'Ficha completa')}
function copyBlockHtml(p,key,label){let value=commercialText(p,key);if(!value)return'';return `<div class="copy-block"><div class="copy-block-head"><b>${esc(label)}</b><button class="btn sm" onclick="copyCommercialField('${p.id}','${key}','${esc(label)}')">⧉ Copiar</button></div><div class="copy-content">${esc(value)}</div></div>`}
function openCommercialForCourse(courseId){let p=state.commercialProfiles.find(x=>x.courseId===courseId);if(p)viewCommercialProfile(p.id);else openCommercialForm(null,courseId)}
