function renderQuickReplies(){let el=document.getElementById('quickRepliesContent');if(!el)return;let q=(document.getElementById('commercialSearch')?.value||'').toLowerCase(),list=state.quickReplies.filter(r=>!q||(r.title+' '+r.category+' '+r.text).toLowerCase().includes(q));el.innerHTML=list.length?`<div class="quick-replies-grid">${list.map(r=>`<div class="card quick-reply-card"><div class="split-actions"><span class="pill">${esc(r.category)}</span><button class="btn sm primary" onclick="copyQuickReply('${r.id}')">⧉ Copiar</button></div><h3>${esc(r.title)}</h3><div class="copy-preview">${esc(r.text)}</div><div class="card-actions"><button class="btn sm" onclick="editQuickReply('${r.id}')">Editar</button><button class="btn sm" onclick="deleteQuickReply('${r.id}')">Eliminar</button></div></div>`).join('')}</div>`:'<div class="card empty">No hay respuestas rápidas. Guarda mensajes como medios de pago, seguimiento o cierre para reutilizarlos.</div>'}
