function txInRange(t,r){return(!r.start||t.date>=r.start)&&(!r.end||t.date<=r.end)}
function previousRange(r){if(!r.start||!r.end)return null;let s=new Date(r.start+'T12:00:00'),e=new Date(r.end+'T12:00:00'),days=Math.round((e-s)/86400000)+1,pe=new Date(s);pe.setDate(pe.getDate()-1);let ps=new Date(pe);ps.setDate(ps.getDate()-days+1);return{start:isoDate(ps),end:isoDate(pe)}}
function revenueOf(list){return list.reduce((s,t)=>s+toPen(t.amount,t.currency),0)}
function percentChange(cur,prev){if(!prev)return cur?100:0;return Math.round((cur-prev)/prev*100)}
