function exportFilteredSalesCSV(){let r=getSalesRange(salesPeriodMode),courseVal=document.getElementById('salesCourse')?.value||'',accountVal=document.getElementById('salesAccount')?.value||'',q=(document.getElementById('salesSearch')?.value||'').toLowerCase(),courseName=state.courses.find(c=>c.id===courseVal)?.name||'';let tx=state.transactions.filter(t=>t.type==='income'&&txInRange(t,r)&&(!courseVal||(t.courseId===courseVal||t.course===courseName))&&(!accountVal||t.account===accountVal)&&(!q||[t.customer,t.course,t.concept,t.category,accountName(t.account)].join(' ').toLowerCase().includes(q)));let head='Fecha,Cliente,Curso,Cuenta,Categoria,Monto,Moneda\n',rows=tx.map(t=>[t.date,t.customer||'',t.course||'',accountName(t.account),t.category||'',t.amount,t.currency].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),blob=new Blob([head+rows],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PASIR-ventas-'+(r.start||'todo')+'-'+(r.end||'todo')+'.csv';a.click();URL.revokeObjectURL(url);toast('Vista de ventas exportada')}
