const PASIR_DEMO_ACCOUNT_IDS=new Set(['a1','a2','a3','a4','a5','a6']);
const PASIR_DEMO_COURSE_IDS=new Set(['c1','c2','c3','c4']);
const PASIR_DEMO_RECEIVABLE_IDS=new Set(['r1','r2']);
const PASIR_DEMO_BUDGET_IDS=new Set(['b1','b2','b3','b4']);
const PASIR_DEMO_TX_CONCEPTS=new Set(['PLC desde cero — venta','Facebook Ads','Variadores de Frecuencia — venta','HMI Industrial — venta','Gasto personal','Hosting y servicios','SIMUPLC — venta','Retiro personal','2 matrículas PLC desde cero','TikTok Ads','Yape → BCP']);
async function removeDemoData(){
  if(!confirm('¿Eliminar únicamente los datos de demostración de PASIR? Tus usuarios, permisos y datos reales se conservarán.'))return;
  const demoTxIds=(state.transactions||[]).filter(t=>PASIR_DEMO_TX_CONCEPTS.has(String(t.concept||'').trim())).map(t=>t.id).filter(Boolean);
  state=normalizeState({...state,
    accounts:(state.accounts||[]).filter(a=>!PASIR_DEMO_ACCOUNT_IDS.has(a.id)),
    courses:(state.courses||[]).filter(c=>!PASIR_DEMO_COURSE_IDS.has(c.id)),
    receivables:(state.receivables||[]).filter(r=>!PASIR_DEMO_RECEIVABLE_IDS.has(r.id)),
    budgets:(state.budgets||[]).filter(b=>!PASIR_DEMO_BUDGET_IDS.has(b.id)),
    transactions:(state.transactions||[]).filter(t=>!PASIR_DEMO_TX_CONCEPTS.has(String(t.concept||'').trim()))
  });
  try{localStorage.setItem('pasir_finanzas_v1',JSON.stringify(state))}catch(e){}
  renderAll();
  if(cloud.ready&&isManager()){
    try{
      for(let i=0;i<demoTxIds.length;i+=100){
        const ids=demoTxIds.slice(i,i+100);
        if(ids.length){let rr=await cloud.client.from('pasir_transactions').delete().eq('workspace_id',cloud.workspace.id).in('id',ids);if(rr.error)throw rr.error}
      }
      await cloudPushState();
      await cloudPullState();
      renderAll();renderTeam();
      toast('Datos de demostración eliminados también de la nube');
      return;
    }catch(e){cloud.error=e?.message||String(e);console.warn('PASIR demo cleanup',e);toast('Se limpiaron localmente, pero falló la nube: '+cloud.error);return}
  }
  toast('Datos de demostración eliminados. Conecta la nube para limpiarlos allí también');
}
