/* Persistencia robusta para PWA móvil: localStorage + IndexedDB. */
function durableDb(){
  return new Promise((resolve,reject)=>{
    if(!('indexedDB' in window))return resolve(null);
    const req=indexedDB.open(V46_DURABLE_DB,1);
    req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(V46_DURABLE_STORE))db.createObjectStore(V46_DURABLE_STORE)};
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}
async function durableGet(key){
  try{const v=localStorage.getItem(key);if(v!==null)return v}catch(e){}
  try{const db=await durableDb();if(!db)return null;return await new Promise((resolve,reject)=>{const tx=db.transaction(V46_DURABLE_STORE,'readonly'),r=tx.objectStore(V46_DURABLE_STORE).get(key);r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error)})}catch(e){return null}
}
async function durableSet(key,value){
  try{localStorage.setItem(key,value)}catch(e){}
  try{const db=await durableDb();if(db)await new Promise((resolve,reject)=>{const tx=db.transaction(V46_DURABLE_STORE,'readwrite');tx.objectStore(V46_DURABLE_STORE).put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}catch(e){}
}
async function durableRemove(key){
  try{localStorage.removeItem(key)}catch(e){}
  try{const db=await durableDb();if(db)await new Promise((resolve,reject)=>{const tx=db.transaction(V46_DURABLE_STORE,'readwrite');tx.objectStore(V46_DURABLE_STORE).delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}catch(e){}
}
async function requestDurableStorage(){
  try{if(navigator.storage?.persist)await navigator.storage.persist()}catch(e){}
}
const PASIR_SUPABASE_STORAGE={
  getItem:async key=>{let v=await durableGet('supabase:'+key);if(v!==null){try{localStorage.setItem(key,v)}catch(e){}}return v},
  setItem:async (key,value)=>{await durableSet('supabase:'+key,value);try{localStorage.setItem(key,value)}catch(e){}},
  removeItem:async key=>{await durableRemove('supabase:'+key);try{localStorage.removeItem(key)}catch(e){}}
};
