saveMovement=async function(){let amount=Number(document.getElementById('mAmount')?.value);if(!amount||amount<=0)return toast('Ingresa un monto mayor a cero');if(modalType==='income'&&!hasPermission('create_sales'))return toast('Sin permiso');if(modalType==='expense'&&!hasPermission('create_expenses'))return toast('Sin permiso');if(isRestrictedRole()&&!['income','expense'].includes(modalType))return toast('Sin permiso');let currency=document.getElementById('mCurrency')?.value||'PEN',date=document.getElementById('mDate')?.value||todayISO(),time=document.getElementById('mTime')?.value||'',concept=document.getElementById('mConcept')?.value||txLabel({type:modalType}),notes=document.getElementById('mNotes')?.value||'',tx=null;if(modalType==='transfer'){let from=document.getElementById('mFrom').value,to=document.getElementById('mTo').value;if(from===to)return toast('Selecciona cuentas diferentes');let a=state.accounts.find(x=>x.id===from),b=state.accounts.find(x=>x.id===to);if(!a||!b)return toast('Selecciona cuentas válidas');if(a.currency!==currency||b.currency!==currency)return toast('Origen y destino deben usar la moneda elegida');if(hasPermission('view_balances')){a.balance-=amount;b.balance+=amount}tx={id:cryptoId(),date,time,type:'transfer',amount,currency,from,to,category:'Transferencia',concept,notes}}else{let account=document.getElementById('mAccount').value,a=state.accounts.find(x=>x.id===account);if(!a)return toast('Selecciona una cuenta');if(a.currency!==currency)return toast('Selecciona la misma moneda de la cuenta');let category=document.getElementById('mCategory')?.value||txLabel({type:modalType});let sign=(modalType==='income'||modalType==='capital')?1:-1;if(hasPermission('view_balances'))a.balance=Number(a.balance||0)+sign*amount;tx={id:cryptoId(),date,time,type:modalType,amount,currency,account,category,concept,notes};if(modalType==='income'){let courseId=document.getElementById('mCourse')?.value||'',c=state.courses.find(x=>x.id===courseId);tx.courseId=courseId||null;tx.course=c?.name||'';tx.customer=document.getElementById('mCustomer')?.value||'';tx.paymentMethod=document.getElementById('mPayment')?.value||'';tx.operation=document.getElementById('mOperation')?.value||'';if(c&&!document.getElementById('mConcept').value)tx.concept=`Venta — ${c.name}`;if(c)tx.category='Venta de curso'}}tx.createdBy=currentUserId();tx.createdByName=currentUserName();tx.createdAt=new Date().toISOString();state.transactions.unshift(tx);localStorage.setItem('pasir_finanzas_v1',JSON.stringify(state));renderAll();closeModal();if(cloud.ready){let ok=await cloudUpsertTransaction(tx);if(ok)toast('Movimiento guardado y sincronizado');else toast('Guardado localmente; pendiente de sincronizar')}else toast('Movimiento guardado correctamente');if(isManager())scheduleCloudPush()}

