function analysisRangeV46(mode=analysisPeriodV46){let n=new Date(),start=null,end=isoDate(n),label='Todo el historial';if(mode==='today'){start=end=isoDate(n);label='Hoy'}else if(mode==='yesterday'){let d=new Date(n);d.setDate(n.getDate()-1);start=end=isoDate(d);label='Ayer'}else if(mode==='week'){let d=new Date(n);d.setDate(n.getDate()-((n.getDay()+6)%7));start=isoDate(d);label='Esta semana'}else if(mode==='lastweek'){let d=new Date(n);d.setDate(n.getDate()-((n.getDay()+6)%7)-7);start=isoDate(d);let e=new Date(d);e.setDate(d.getDate()+6);end=isoDate(e);label='Semana pasada'}else if(mode==='month'){start=isoDate(new Date(n.getFullYear(),n.getMonth(),1));label='Este mes'}else if(mode==='lastmonth'){let d=new Date(n.getFullYear(),n.getMonth()-1,1);start=isoDate(d);end=isoDate(new Date(d.getFullYear(),d.getMonth()+1,0));label='Mes pasado'}else if(mode==='last3'){start=isoDate(new Date(n.getFullYear(),n.getMonth()-2,1));label='Últimos 3 meses'}else if(mode==='last6'){start=isoDate(new Date(n.getFullYear(),n.getMonth()-5,1));label='Últimos 6 meses'}else if(mode==='last12'){start=isoDate(new Date(n.getFullYear(),n.getMonth()-11,1));label='Últimos 12 meses'}else if(mode==='year'){start=`${n.getFullYear()}-01-01`;end=`${n.getFullYear()}-12-31`;label='Este año'}else if(mode==='lastyear'){start=`${n.getFullYear()-1}-01-01`;end=`${n.getFullYear()-1}-12-31`;label='Año anterior'}else if(mode==='custom'){start=document.getElementById('analysisFrom')?.value||isoDate(new Date(n.getFullYear(),n.getMonth(),1));end=document.getElementById('analysisTo')?.value||isoDate(n);label=`${start} — ${end}`}else if(mode==='all'){end=null}return{start,end,label}}
function analysisMetricValue(view,r){let tx=state.transactions.filter(t=>txInRange(t,r)),inc=revenueOf(tx.filter(t=>t.type==='income')),exp=revenueOf(tx.filter(t=>t.type==='expense')),inv=projectCostsInRange(r).reduce((s,c)=>s+Number(c.amount||0),0),cash=tx.reduce((s,t)=>{let v=toPen(t.amount,t.currency);if(t.type==='income'||t.type==='capital')return s+v;if(['expense','personal','owner_withdrawal'].includes(t.type))return s-v;return s},0);if(view==='sales')return inc;if(view==='expenses')return exp;if(view==='profit')return inc-exp;if(view==='investment')return inv;if(view==='cashflow')return cash;return inc-exp}
function bucketInfo(date,group){let d=new Date(date+'T12:00:00'),y=d.getFullYear(),m=d.getMonth();if(group==='day')return{key:isoDate(d),label:d.toLocaleDateString('es-PE',{day:'2-digit',month:'short'}),start:isoDate(d),end:isoDate(d)};if(group==='year')return{key:String(y),label:String(y),start:`${y}-01-01`,end:`${y}-12-31`};if(group==='quarter'){let q=Math.floor(m/3),s=new Date(y,q*3,1),e=new Date(y,q*3+3,0);return{key:`${y}-T${q+1}`,label:`T${q+1} ${y}`,start:isoDate(s),end:isoDate(e)}}if(group==='week'){let s=new Date(d);s.setDate(d.getDate()-((d.getDay()+6)%7));let e=new Date(s);e.setDate(s.getDate()+6);return{key:isoDate(s),label:s.toLocaleDateString('es-PE',{day:'2-digit',month:'short'}),start:isoDate(s),end:isoDate(e)}}let s=new Date(y,m,1),e=new Date(y,m+1,0);return{key:`${y}-${String(m+1).padStart(2,'0')}`,label:d.toLocaleString('es-PE',{month:'short',year:'2-digit'}),start:isoDate(s),end:isoDate(e)}}
function analysisItemsDates(view,r){let dates=[];state.transactions.filter(t=>txInRange(t,r)).forEach(t=>dates.push(t.date));if(view==='investment'||view==='compare')projectCostsInRange(r).forEach(c=>c.date&&dates.push(c.date));return dates}
function analysisBuckets(view,r,group){let dates=analysisItemsDates(view,r);if(!dates.length){let n=new Date();dates=[r.start||isoDate(new Date(n.getFullYear(),n.getMonth()-5,1)),r.end||isoDate(n)]}let map=new Map();dates.forEach(date=>{let b=bucketInfo(date,group);if(!map.has(b.key))map.set(b.key,b)});let buckets=[...map.values()].sort((a,b)=>a.start.localeCompare(b.start));if(r.start&&r.end){let cur=new Date(r.start+'T12:00:00'),end=new Date(r.end+'T12:00:00'),guard=0;while(cur<=end&&guard++<500){let b=bucketInfo(isoDate(cur),group);if(!map.has(b.key)){map.set(b.key,b);buckets.push(b)}if(group==='day')cur.setDate(cur.getDate()+1);else if(group==='week')cur.setDate(cur.getDate()+7);else if(group==='month')cur.setMonth(cur.getMonth()+1);else if(group==='quarter')cur.setMonth(cur.getMonth()+3);else cur.setFullYear(cur.getFullYear()+1)}buckets=[...map.values()].sort((a,b)=>a.start.localeCompare(b.start))}return buckets.map(b=>({...b,value:analysisMetricValue(view,b),metrics:analysisMetrics(b)}))}
function analysisViewMeta(v){return {sales:['Ventas','↗','Facturación e historial de ventas'],expenses:['Gastos','−','Gastos operativos del negocio'],profit:['Utilidad','◆','Ingresos menos gastos operativos'],investment:['Inversión','▰','Costos registrados en proyectos'],cashflow:['Flujo de caja','⇄','Entradas y salidas netas, sin transferencias'],compare:['Comparativo general','◫','Ventas vs gastos vs utilidad']}[v]||['Análisis','✦','']}
