function breakdownRows(view,r,by){let m={};if(view==='investment'){projectCostsInRange(r).forEach(c=>{let k=by==='project'?(c.project||'Sin proyecto'):(c.category||'Sin categoría');m[k]=(m[k]||0)+Number(c.amount||0)})}else{state.transactions.filter(t=>txInRange(t,r)).forEach(t=>{if(view==='sales'&&t.type!=='income')return;if(view==='expenses'&&t.type!=='expense')return;if(view==='cashflow'&&!['income','capital','expense','personal','owner_withdrawal'].includes(t.type))return;let k=by==='course'?(t.course||'Sin vincular'):by==='category'?(t.category||'Sin categoría'):by==='account'?accountName(t.account):'Total',v=toPen(t.amount,t.currency);if(view==='cashflow'&&['expense','personal','owner_withdrawal'].includes(t.type))v=-v;m[k]=(m[k]||0)+v})}return Object.entries(m).map(([name,value])=>({name,value})).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value))}
