renderPasirAnalysis=function(){let el=document.getElementById('pasirAnalysisContent');if(!el)return;if(!hasPermission('view_financial_analysis')&&isRestrictedRole()){el.innerHTML='<div class="card empty">No tienes permiso para revisar análisis financiero.</div>';return}let month=analysisRangeV46('month'),mm=analysisMetrics(month),allInv=projectCostsInRange(month).reduce((s,c)=>s+Number(c.amount||0),0);if(analysisViewV46==='home'){let cards=[['sales','↗','Ventas',fmt(mm.income),`${mm.sales} operaciones este mes`],['expenses','−','Gastos',fmt(mm.expense),'Gastos operativos del mes'],['profit','◆','Utilidad',fmt(mm.profit),`Margen ${mm.margin}%`],['investment','▰','Inversión',fmt(allInv),'Producción y proyectos'],['cashflow','⇄','Flujo de caja',fmt(analysisMetricValue('cashflow',month)),'Entradas menos salidas'],['compare','◫','Comparativo general','Abrir','Ventas vs gastos vs utilidad']];el.innerHTML=`<div class="hero"><div><h1>Centro de Análisis</h1><p>Elige exactamente qué quieres estudiar. Cada análisis tiene sus propios filtros, gráfico y detalle.</p></div></div><div class="analysis-hub-grid">${cards.map(c=>`<button class="card analysis-hub-card" onclick="setAnalysisView('${c[0]}')"><div class="hub-icon">${c[1]}</div><div class="hub-title">${c[2]}</div><div class="hub-value">${c[3]}</div><div class="hub-desc">${c[4]}</div></button>`).join('')}</div><div class="card section"><h2 style="margin-top:0">Cómo usarlo</h2><p class="muted" style="font-size:12px;line-height:1.6">Por ejemplo: entra a <b>Ventas</b>, selecciona “Últimos 12 meses”, agrupa por “Mes” y desglosa por “Curso”. El gráfico mostrará solo ventas y podrás tocar cualquier barra para revisar las operaciones que la componen.</p></div>`;return}
 let meta=analysisViewMeta(analysisViewV46),r=analysisRangeV46(),value=analysisMetricValue(analysisViewV46,r),prev=previousRangeV46(r),prevValue=prev?analysisMetricValue(analysisViewV46,prev):0,ch=prev?percentChange(value,prevValue):null,buckets=analysisBuckets(analysisViewV46==='compare'?'profit':analysisViewV46,r,analysisGroupV46),max=Math.max(1,...buckets.flatMap(b=>analysisViewV46==='compare'?[b.metrics.income,b.metrics.expense,Math.abs(b.metrics.profit)]:[Math.abs(b.value)]));let chart=buckets.map(b=>{if(analysisViewV46==='compare')return `<div class="analysis-bucket"><div class="analysis-bucket-bars"><button class="analysis-series-bar sales" style="height:${Math.max(3,b.metrics.income/max*180)}px" title="Ventas ${fmt(b.metrics.income)}" onclick="openAnalysisBucket('${b.start}','${b.end}','sales')"></button><button class="analysis-series-bar expenses" style="height:${Math.max(3,b.metrics.expense/max*180)}px" title="Gastos ${fmt(b.metrics.expense)}" onclick="openAnalysisBucket('${b.start}','${b.end}','expenses')"></button><button class="analysis-series-bar profit" style="height:${Math.max(3,Math.abs(b.metrics.profit)/max*180)}px" title="Utilidad ${fmt(b.metrics.profit)}" onclick="openAnalysisBucket('${b.start}','${b.end}','profit')"></button></div><div class="analysis-bucket-label">${b.label}</div></div>`;return `<div class="analysis-bucket"><div class="analysis-bucket-bars"><button class="analysis-single-bar ${b.value<0?'negative':''}" style="height:${Math.max(3,Math.abs(b.value)/max*180)}px" title="${fmt(b.value)}" onclick="openAnalysisBucket('${b.start}','${b.end}','${analysisViewV46}')"></button></div><div class="analysis-bucket-label">${b.label}</div></div>`}).join('');let optionsBy=analysisViewV46==='sales'?[['total','Sin desglose'],['course','Por curso / producto'],['account','Por cuenta / medio']]:analysisViewV46==='expenses'?[['total','Sin desglose'],['category','Por categoría'],['account','Por cuenta']]:analysisViewV46==='investment'?[['total','Sin desglose'],['project','Por proyecto'],['category','Por categoría']]:analysisViewV46==='cashflow'?[['total','Sin desglose'],['account','Por cuenta']]:[['total','Sin desglose']];let br=analysisBreakdownV46==='total'?[]:breakdownRows(analysisViewV46,r,analysisBreakdownV46),brMax=Math.max(1,...br.map(x=>Math.abs(x.value)));let breakdown=br.length?`<div class="card section"><div class="section-head"><h2>Desglose</h2><span class="muted" style="font-size:11px">${r.label}</span></div><div class="breakdown-list">${br.slice(0,20).map(x=>`<div class="breakdown-row"><b>${esc(x.name)}</b><div class="breakdown-track"><i style="width:${Math.abs(x.value)/brMax*100}%"></i></div><strong>${fmt(x.value)}</strong></div>`).join('')}</div></div>`:'';let table=buckets.slice().reverse().map(b=>analysisViewV46==='compare'?`<tr><td>${b.label}</td><td>${fmt(b.metrics.income)}</td><td>${fmt(b.metrics.expense)}</td><td>${fmt(b.metrics.profit)}</td></tr>`:`<tr class="clickable-card" onclick="openAnalysisBucket('${b.start}','${b.end}','${analysisViewV46}')"><td>${b.label}</td><td>${fmt(b.value)}</td><td>${b.metrics.sales}</td></tr>`).join('');el.innerHTML=`<div class="analysis-detail-head"><div><button class="btn sm analysis-back" onclick="setAnalysisView('home')">← Centro de Análisis</button><h1 style="margin:12px 0 4px">${meta[1]} Análisis de ${meta[0]}</h1><div class="muted">${meta[2]}</div></div><div class="quick"><button class="btn" onclick="showScreen('reports')">Reportes</button></div></div><div class="card analysis-filter-panel"><div class="analysis-filter-grid"><div class="field"><label>Periodo</label><select onchange="analysisPeriodV46=this.value;renderPasirAnalysis()">${options([['today','Hoy'],['yesterday','Ayer'],['week','Esta semana'],['lastweek','Semana pasada'],['month','Este mes'],['lastmonth','Mes pasado'],['last3','Últimos 3 meses'],['last6','Últimos 6 meses'],['last12','Últimos 12 meses'],['year','Este año'],['lastyear','Año anterior'],['all','Todo el historial']],analysisPeriodV46)}</select></div><div class="field"><label>Agrupar por</label><select onchange="analysisGroupV46=this.value;renderPasirAnalysis()">${options([['day','Día'],['week','Semana'],['month','Mes'],['quarter','Trimestre'],['year','Año']],analysisGroupV46)}</select></div><div class="field"><label>Desglosar por</label><select onchange="analysisBreakdownV46=this.value;renderPasirAnalysis()">${options(optionsBy,analysisBreakdownV46)}</select></div><div class="field"><label>Vista actual</label><select onchange="setAnalysisView(this.value)">${options([['sales','Ventas'],['expenses','Gastos'],['profit','Utilidad'],['investment','Inversión'],['cashflow','Flujo de caja'],['compare','Comparativo general']],analysisViewV46)}</select></div></div></div><div class="grid stats analysis-stats"><div class="card stat"><div class="label">${meta[0]} · ${r.label}</div><div class="value">${analysisViewV46==='compare'?fmt(analysisMetrics(r).income):fmt(value)}</div><div class="trend">${analysisViewV46==='compare'?'Ventas del periodo':(ch===null?'Periodo seleccionado':`${ch>=0?'+':''}${ch}% vs periodo anterior`)}</div></div><div class="card stat"><div class="label">Operaciones / ventas</div><div class="value">${analysisMetrics(r).sales}</div><div class="trend">Movimientos de ingreso</div></div><div class="card stat"><div class="label">Periodo anterior</div><div class="value">${prev?fmt(prevValue):'—'}</div><div class="trend">Referencia comparable</div></div><div class="card stat"><div class="label">Agrupación</div><div class="value" style="font-size:20px">${{day:'Diaria',week:'Semanal',month:'Mensual',quarter:'Trimestral',year:'Anual'}[analysisGroupV46]}</div><div class="trend">${buckets.length} bloques</div></div></div><div class="card section"><div class="section-head"><div><h2>Gráfico · ${meta[0]}</h2><div class="muted" style="font-size:11px;margin-top:4px">Toca una barra para abrir el detalle real de ese periodo.</div></div>${analysisViewV46==='compare'?'<div class="analysis-legend"><span><i class="legend-swatch income"></i>Ventas</span><span><i class="legend-swatch expense"></i>Gastos</span><span><i class="legend-swatch profit"></i>Utilidad</span></div>':''}</div><div class="analysis-chart-v46">${chart||'<div class="empty">Sin datos</div>'}</div></div>${breakdown}<div class="card section"><div class="section-head"><h2>Historial agrupado</h2><span class="muted" style="font-size:11px">Toca una fila para ver sus operaciones</span></div><div class="table-wrap"><table class="table"><thead>${analysisViewV46==='compare'?'<tr><th>Periodo</th><th>Ventas</th><th>Gastos</th><th>Utilidad</th></tr>':'<tr><th>Periodo</th><th>Valor</th><th>Ventas registradas</th></tr>'}</thead><tbody>${table}</tbody></table></div></div>`}

/* =================== NUBE Y EQUIPO =================== */
async function saveCloudSessionBackup(session){
  try{
    if(!session?.access_token||!session?.refresh_token)return;
    await durableSet(V46_AUTH_BACKUP_KEY,JSON.stringify({
      access_token:session.access_token,
      refresh_token:session.refresh_token,
      expires_at:session.expires_at||null,
      saved_at:Date.now()
    }));
    await requestDurableStorage();
  }catch(e){console.warn('PASIR no pudo respaldar la sesión',e)}
}
async function getCloudSessionBackup(){
  try{
    let raw=await durableGet(V46_AUTH_BACKUP_KEY),s=JSON.parse(raw||'null');
    return s&&s.access_token&&s.refresh_token?s:null;
  }catch(e){return null}
}
async function clearCloudSessionBackup(){await durableRemove(V46_AUTH_BACKUP_KEY)}
async function restoreCloudSession(){
  if(cloudRestoringSession||!cloud.configured||!cloud.client)return false;
  cloudRestoringSession=true;
  try{
    let {data,error}=await cloud.client.auth.getSession();
    let session=data?.session||null;
    if(!session){
      let backup=await getCloudSessionBackup();
      if(backup){
        let restored=await cloud.client.auth.setSession({access_token:backup.access_token,refresh_token:backup.refresh_token});
        if(!restored.error)session=restored.data?.session||null;
      }
    }
    if(session){
      saveCloudSessionBackup(session);
      cloud.user=session.user||null;
      if(cloud.user&&!cloud.ready)await loadCloudContext();
      updateIdentityUI();updateConnectionStatus();
      return true;
    }
    cloud.user=null;cloud.ready=false;updateIdentityUI();updateConnectionStatus();
    return false;
  }catch(e){cloud.error=e?.message||String(e);return false}
  finally{cloudRestoringSession=false}
}
function getCloudConfig(){try{return JSON.parse(localStorage.getItem(V46_CLOUD_CONFIG_KEY)||'null')}catch(e){return null}}
async function getCloudConfigDurable(){let cfg=getCloudConfig();if(cfg?.url&&cfg?.key)return cfg;try{let raw=await durableGet(V46_CLOUD_CONFIG_KEY);cfg=JSON.parse(raw||'null');if(cfg?.url&&cfg?.key){try{localStorage.setItem(V46_CLOUD_CONFIG_KEY,JSON.stringify(cfg))}catch(e){};return cfg}}catch(e){}return null}
async function setCloudConfig(url,key){const cfg={url:(url||'').trim(),key:(key||'').trim()};await durableSet(V46_CLOUD_CONFIG_KEY,JSON.stringify(cfg));await requestDurableStorage();cloud.configured=!!(cfg.url&&cfg.key);return cfg}
async function clearCloudConfig(){if(!confirm('¿Desconectar esta instalación de Supabase? Los datos locales no se borrarán.'))return;await durableRemove(V46_CLOUD_CONFIG_KEY);await clearCloudSessionBackup();cloud={client:null,user:null,workspace:null,membership:null,team:[],configured:false,ready:false,syncing:false,lastSync:null,error:null};location.reload()}
async function initCloud(){let cfg=await getCloudConfigDurable();cloud.configured=!!(cfg?.url&&cfg?.key);cloud.error=null;if(!cloud.configured){cloud.client=null;cloud.user=null;cloud.ready=false;renderCloudPanels();updateConnectionStatus();return false}if(!window.supabase){cloud.error='No se pudo cargar la librería de Supabase';renderCloudPanels();updateConnectionStatus();return false}try{cloud.client=window.supabase.createClient(cfg.url,cfg.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storage:PASIR_SUPABASE_STORAGE}});let result=await cloud.client.auth.getSession();let session=result?.data?.session||null;if(!session){let backup=await getCloudSessionBackup();if(backup){let restored=await cloud.client.auth.setSession({access_token:backup.access_token,refresh_token:backup.refresh_token});if(!restored.error)session=restored.data?.session||null}}cloud.user=session?.user||null;if(session)await saveCloudSessionBackup(session);cloud.client.auth.onAuthStateChange((event,s)=>{if(s)void saveCloudSessionBackup(s);cloud.user=s?.user||null;if(!s){cloud.workspace=null;cloud.membership=null;cloud.ready=false}setTimeout(()=>{if(cloud.user)loadCloudContext();else{renderCloudPanels();renderNav();updateConnectionStatus()}},50)});if(cloud.user)await loadCloudContext();else{cloud.ready=false;renderCloudPanels()}return true}catch(e){cloud.error=e?.message||String(e);cloud.client=null;cloud.ready=false;renderCloudPanels();return false}finally{renderNav();updateConnectionStatus();updateIdentityUI()}}
async function loadCloudContext(){if(!cloud.client||!cloud.user)return;try{let {data:mem,error}=await cloud.client.from('pasir_memberships').select('*').eq('user_id',cloud.user.id).eq('active',true).limit(1).maybeSingle();if(error)throw error;if(!mem){let {data:owned}=await cloud.client.from('pasir_workspaces').select('*').eq('owner_id',cloud.user.id).limit(1).maybeSingle();if(owned){await cloud.client.from('pasir_memberships').upsert({workspace_id:owned.id,user_id:cloud.user.id,invited_email:cloud.user.email,display_name:cloud.user.email,role:'owner',permissions:{},active:true});return loadCloudContext()}cloud.membership=null;cloud.workspace=null;cloud.ready=false;renderCloudPanels();renderNav();renderTeam();updateIdentityUI();return}cloud.membership=mem;let {data:ws}=await cloud.client.from('pasir_workspaces').select('*').eq('id',mem.workspace_id).single();cloud.workspace=ws;cloud.ready=true;await cloudPullState();await loadTeamMembers();updateIdentityUI();renderNav();let active=document.querySelector('.screen.active')?.id.replace('screen-','');if(!allowedScreen(active))showScreen(isRestrictedRole()?'operator-home':'summary');else renderAll();renderCloudPanels()}catch(e){cloud.error=e.message;cloud.ready=false;renderCloudPanels();toast('No se pudo cargar la nube: '+e.message)}}
function accountTxDelta(id,transactions=state.transactions){return transactions.reduce((s,t)=>{let v=Number(t.amount||0);if(t.type==='transfer'){if(t.from===id)s-=v;if(t.to===id)s+=v}else if(t.account===id){if(t.type==='income'||t.type==='capital')s+=v;else if(['expense','personal','owner_withdrawal'].includes(t.type))s-=v}return s},0)}
function sharedDataForCloud(){return{version:'4.7',courses:state.courses,commercialProfiles:state.commercialProfiles,quickReplies:state.quickReplies,goals:state.goals.filter(g=>g.teamVisible!==false).map(g=>({...g,teamProgress:g.kind==='financial'?goalCurrent(g):goalCurrent(g)})),projects:state.projects.filter(p=>p.teamVisible).map(p=>({...p,costs:[]})),paymentMethods:state.accounts.map(a=>({id:a.id,name:a.name,currency:a.currency,type:a.type})),updatedAt:new Date().toISOString()}}
function privateDataForCloud(){return{version:'4.7',rates:state.rates,accounts:state.accounts.map(a=>({...a,openingBalance:Number(a.balance||0)-accountTxDelta(a.id)})),receivables:state.receivables,payables:state.payables,budgets:state.budgets,goals:state.goals,projects:state.projects,updatedAt:new Date().toISOString()}}
function dbTx(t){return{id:t.id,workspace_id:cloud.workspace.id,tx_date:t.date,tx_time:t.time||null,type:t.type,amount:Number(t.amount||0),currency:t.currency||'PEN',account_id:t.account||null,from_account_id:t.from||null,to_account_id:t.to||null,category:t.category||'',concept:t.concept||'',notes:t.notes||'',course_id:t.courseId||null,course_name:t.course||'',customer:t.customer||'',payment_method:t.paymentMethod||'',operation_number:t.operation||'',created_by:t.createdBy&&t.createdBy!=='local-owner'?t.createdBy:cloud.user.id,created_by_name:t.createdByName||currentUserName(),updated_by:cloud.user.id}}
function fromDbTx(t){return{id:t.id,date:t.tx_date,time:(t.tx_time||'').slice(0,5),type:t.type,amount:Number(t.amount||0),currency:t.currency,account:t.account_id,from:t.from_account_id,to:t.to_account_id,category:t.category,concept:t.concept,notes:t.notes,courseId:t.course_id,course:t.course_name,customer:t.customer,paymentMethod:t.payment_method,operation:t.operation_number,createdBy:t.created_by,createdByName:t.created_by_name||'Usuario',createdAt:t.created_at}}
async function cloudUpsertTransaction(t){if(!cloud.ready)return false;try{let {error}=await cloud.client.from('pasir_transactions').upsert(dbTx(t),{onConflict:'workspace_id,id'});if(error)throw error;cloud.lastSync=new Date();updateConnectionStatus();return true}catch(e){console.warn(e);cloud.error=e.message;return false}}
async function cloudPushState(){if(!cloud.ready||!isManager()||cloud.syncing)return;cloud.syncing=true;try{let sh=sharedDataForCloud(),pr=privateDataForCloud();let r1=await cloud.client.from('pasir_shared_data').upsert({workspace_id:cloud.workspace.id,data:sh,updated_by:cloud.user.id});if(r1.error)throw r1.error;let r2=await cloud.client.from('pasir_private_data').upsert({workspace_id:cloud.workspace.id,data:pr,updated_by:cloud.user.id});if(r2.error)throw r2.error;if(state.transactions.length){let rows=state.transactions.map(t=>dbTx(t));for(let i=0;i<rows.length;i+=200){let rr=await cloud.client.from('pasir_transactions').upsert(rows.slice(i,i+200),{onConflict:'workspace_id,id'});if(rr.error)throw rr.error}}cloud.lastSync=new Date();cloud.error=null}catch(e){cloud.error=e.message;console.warn('PASIR cloud push',e)}finally{cloud.syncing=false;updateConnectionStatus();renderCloudPanels()}}
function scheduleCloudPush(){if(!cloud.ready||!isManager())return;clearTimeout(cloudPushTimer);cloudPushTimer=setTimeout(cloudPushState,700)}
async function cloudPullState(){if(!cloud.ready)return;cloud.syncing=true;try{let {data:sharedRow,error:se}=await cloud.client.from('pasir_shared_data').select('data').eq('workspace_id',cloud.workspace.id).maybeSingle();if(se)throw se;let shared=sharedRow?.data||{};let {data:txRowsDb,error:te}=await cloud.client.from('pasir_transactions').select('*').eq('workspace_id',cloud.workspace.id).order('tx_date',{ascending:false});if(te)throw te;let tx=(txRowsDb||[]).map(fromDbTx);if(isManager()||hasPermission('view_balances')){let {data:privateRow,error:pe}=await cloud.client.from('pasir_private_data').select('data').eq('workspace_id',cloud.workspace.id).maybeSingle();if(pe)throw pe;let pr=privateRow?.data||{};let accounts=(pr.accounts||[]).map(a=>({...a,balance:Number(a.openingBalance??a.balance??0)+accountTxDelta(a.id,tx)}));state=normalizeState({rates:pr.rates||state.rates,accounts,courses:shared.courses||state.courses,receivables:pr.receivables||[],payables:pr.payables||[],budgets:pr.budgets||[],goals:pr.goals||shared.goals||[],projects:pr.projects||shared.projects||[],commercialProfiles:shared.commercialProfiles||[],quickReplies:shared.quickReplies||[],transactions:tx});}else{state=normalizeState({rates:{USD:3.65,USDT:3.65},accounts:(shared.paymentMethods||[]).map(a=>({...a,balance:0,hiddenBalance:true})),courses:hasPermission('view_products')?(shared.courses||[]):[],receivables:[],payables:[],budgets:[],goals:hasPermission('view_goals')?(shared.goals||[]):[],projects:hasPermission('view_projects')?(shared.projects||[]):[],commercialProfiles:hasPermission('view_commercial')?(shared.commercialProfiles||[]):[],quickReplies:hasPermission('view_commercial')?(shared.quickReplies||[]):[],transactions:hasPermission('view_own_entries')?tx:[]});}ensureV46State();localStorage.setItem('pasir_finanzas_v1',JSON.stringify(state));cloud.lastSync=new Date();cloud.error=null}catch(e){cloud.error=e.message;console.warn('PASIR cloud pull',e)}finally{cloud.syncing=false;updateConnectionStatus()}}
async function syncCloudNow(){if(!cloud.configured)return openCloudSetup();if(!cloud.user)return openCloudAuth();if(!cloud.ready)return toast('Primero crea o únete a un espacio PASIR');toast('Sincronizando…');if(isManager())await cloudPushState();await cloudPullState();await loadTeamMembers();renderAll();renderTeam();toast('Sincronización completada')}

function openCloudPanel(){if(localRolePreview){localRolePreview='';localStorage.removeItem('pasir_role_preview');renderNav();showScreen('summary');toast('Volviste a la vista Propietario');return}if(!cloud.configured)return openCloudSetup();if(!cloud.user)return openCloudAuth();showScreen(isManager()?'team':'operator-home')}
function openCloudSetup(){let cfg=getCloudConfig()||{};openEntityModal({eyebrow:'NUBE PASIR · SUPABASE',title:'Conectar PASIR a la nube',subtitle:'Pega la URL y la anon key de tu proyecto Supabase. La service_role key nunca debe colocarse aquí.',saveLabel:'Guardar conexión',body:formSection('☁','Credenciales públicas',`<div class="form-grid"><div class="field span-2"><label class="required">Project URL</label><input id="cloudUrl" value="${esc(cfg.url||'')}" placeholder="https://xxxx.supabase.co"></div><div class="field span-2"><label class="required">Anon / publishable key</label><textarea id="cloudKey" style="min-height:90px" placeholder="eyJ..."></textarea></div></div>`)+`<div class="restricted-note">Antes de conectar, ejecuta el archivo <b>supabase-schema.sql</b> que acompaña esta versión en el SQL Editor de Supabase. Así se crean usuarios, permisos y políticas RLS.</div>`,onSave:async()=>{let u=val('cloudUrl'),k=val('cloudKey');if(!u||!k)return toast('Completa URL y anon key');await setCloudConfig(u,k);closeEntityModal();toast('Conexión guardada. Conectando…');await initCloud();renderNav();renderAll();updateConnectionStatus();if(cloud.configured&&!cloud.user)toast('Supabase conectado. Ahora crea o inicia sesión.')}})}
function openCloudAuth(){openEntityModal({eyebrow:'NUBE PASIR · ACCESO',title:'Iniciar sesión',subtitle:'Cada persona debe usar su propia cuenta para que PASIR registre quién creó cada movimiento.',saveLabel:'Iniciar sesión',body:formSection('✉','Cuenta',`<div class="form-grid"><div class="field span-2"><label>Correo</label><input id="authEmail" type="email" placeholder="usuario@correo.com"></div><div class="field span-2"><label>Contraseña</label><input id="authPassword" type="password" placeholder="Mínimo 6 caracteres"></div></div>`)+`<div class="split-actions"><span class="cloud-setup-note">¿Es tu primera cuenta?</span><button type="button" class="btn sm" onclick="cloudSignUp()">Crear cuenta</button></div>`,onSave:cloudSignIn})}
async function cloudSignIn(){let email=val('authEmail'),password=val('authPassword');if(!email||!password)return toast('Completa correo y contraseña');let {data,error}=await cloud.client.auth.signInWithPassword({email,password});if(error)return toast(error.message);if(data.session)await saveCloudSessionBackup(data.session);cloud.user=data.user;closeEntityModal();toast('Sesión iniciada y recordada');await loadCloudContext();if(cloud.user&&!cloud.ready){showScreen('team');renderTeam()}}
async function cloudSignUp(){let email=val('authEmail'),password=val('authPassword');if(!email||password.length<6)return toast('Escribe correo y contraseña de al menos 6 caracteres');let {data,error}=await cloud.client.auth.signUp({email,password});if(error)return toast(error.message);if(data.session)await saveCloudSessionBackup(data.session);toast(data.session?'Cuenta creada':'Cuenta creada. Revisa tu correo para confirmarla.');if(data.session){cloud.user=data.user;closeEntityModal();await loadCloudContext()}}
async function cloudSignOut(){if(!cloud.client)return;await cloud.client.auth.signOut();await clearCloudSessionBackup();cloud.user=null;cloud.workspace=null;cloud.membership=null;cloud.ready=false;localRolePreview='';renderNav();showScreen('summary');renderCloudPanels();toast('Sesión cerrada')}
